var __line = 1
  , __lines = "<%- include('partials/layouts/main-start') -%>\n\n<section class=\"hero\" style=\"padding:60px 0 40px;\">\n  <div class=\"container\">\n    <div style=\"max-width:800px;margin:0 auto;text-align:center;\">\n      <span class=\"section-eyebrow\">🇦🇺 About United Credit Bank</span>\n      <h1 style=\"font-size:3rem;margin:16px 0;\">42 years of banking, built for Australians.</h1>\n      <p class=\"hero-subtitle\" style=\"margin:0 auto 24px;\">From a small Sydney credit union in 1984 to one of Australia's most trusted banks — we've grown, but our values haven't changed.</p>\n    </div>\n  </div>\n</section>\n\n<section class=\"section section-alt\">\n  <div class=\"container\">\n    <div class=\"grid-2\" style=\"align-items:center;\">\n      <div>\n        <span class=\"section-eyebrow\">Our Story</span>\n        <h2>Founded by Australians, for Australians.</h2>\n        <p>United Credit Bank began in 1984 when a group of 47 Sydneysiders pooled their savings into a community credit union. They believed banking should put people before profits — and that belief still guides everything we do today.</p>\n        <p>Four decades later, we serve over 250,000 customers across Australia with 58 branches from Hobart to Darwin. We remain proudly Australian-owned, with our headquarters still at 1 Martin Place in Sydney, where it all began.</p>\n        <ul class=\"feature-list\" style=\"margin-top:16px;\">\n          <li>Proudly Australian-owned — no overseas shareholders</li>\n          <li>APRA regulated and government guaranteed (up to $250K)</li>\n          <li>Profits reinvested into better rates for customers</li>\n          <li>Committed to net-zero carbon by 2035</li>\n        </ul>\n      </div>\n      <div>\n        <div class=\"card\" style=\"overflow:hidden;\">\n          <div style=\"aspect-ratio:4/3;background:linear-gradient(135deg,var(--primary) 0%,var(--primary-dark) 100%);display:flex;align-items:center;justify-content:center;font-size:8rem;\">🏦</div>\n          <div class=\"card-body\">\n            <div class=\"grid-3\" style=\"margin:0;text-align:center;\">\n              <div>\n                <div style=\"font-size:2rem;font-weight:800;color:var(--primary);\">1984</div>\n                <div style=\"font-size:0.8rem;color:var(--text-light);text-transform:uppercase;letter-spacing:0.05em;\">Founded</div>\n              </div>\n              <div>\n                <div style=\"font-size:2rem;font-weight:800;color:var(--primary);\">250K+</div>\n                <div style=\"font-size:0.8rem;color:var(--text-light);text-transform:uppercase;letter-spacing:0.05em;\">Customers</div>\n              </div>\n              <div>\n                <div style=\"font-size:2rem;font-weight:800;color:var(--primary);\">58</div>\n                <div style=\"font-size:0.8rem;color:var(--text-light);text-transform:uppercase;letter-spacing:0.05em;\">Branches</div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section class=\"section\">\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <span class=\"section-eyebrow\">Our Values</span>\n      <h2>What drives us every day</h2>\n      <p>Six core values that guide every decision we make, from the boardroom to the branch counter.</p>\n    </div>\n    <div class=\"grid-3\">\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\">🤝</div>\n        <h3>Integrity First</h3>\n        <p>We do the right thing — even when no one is watching. No hidden fees, no fine print, no tricks. Just honest banking.</p>\n      </div>\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\">🌱</div>\n        <h3>Sustainable Future</h3>\n        <p>We're committed to funding Australia's transition to renewable energy and a sustainable economy.</p>\n      </div>\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\">❤️</div>\n        <h3>Community Focus</h3>\n        <p>Every year we donate 3% of profits to Australian community organisations, from surf lifesaving to rural fire services.</p>\n      </div>\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\">🔬</div>\n        <h3>Innovation</h3>\n        <p>From Australia's first mobile cheque deposit to AI-powered budgeting tools — we lead with tech that works.</p>\n      </div>\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\">🏳️‍🌈</div>\n        <h3>Inclusion</h3>\n        <p>We're proud to be an Employer of Choice for Gender Equality and support First Nations communities through our RAP.</p>\n      </div>\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\">🛡️</div>\n        <h3>Security</h3>\n        <p>Your money's safety is non-negotiable. Bank-grade encryption, 24/7 fraud monitoring, and a zero-liability guarantee.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section class=\"section section-alt\">\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <span class=\"section-eyebrow\">Leadership</span>\n      <h2>Meet the team</h2>\n      <p>A team of experienced bankers and fintech leaders with deep roots in Australian financial services.</p>\n    </div>\n    <div class=\"grid-4\" style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:20px;\">\n      <div class=\"card\">\n        <div style=\"aspect-ratio:1;background:linear-gradient(135deg,var(--primary-alpha),var(--bg-gray));display:flex;align-items:center;justify-content:center;font-size:4rem;\">👩‍💼</div>\n        <div class=\"card-body\" style=\"padding:20px;\">\n          <h4>Jennifer Davidson AO</h4>\n          <div style=\"font-size:0.85rem;color:var(--primary);font-weight:600;margin-bottom:8px;\">Chief Executive Officer</div>\n          <p style=\"font-size:0.85rem;margin:0;\">30+ years in Australian banking. Former ANZ Group Executive. Chair, Australian Banking Association 2024-2026.</p>\n        </div>\n      </div>\n      <div class=\"card\">\n        <div style=\"aspect-ratio:1;background:linear-gradient(135deg,var(--primary-alpha),var(--bg-gray));display:flex;align-items:center;justify-content:center;font-size:4rem;\">👨‍💼</div>\n        <div class=\"card-body\" style=\"padding:20px;\">\n          <h4>Michael Chen</h4>\n          <div style=\"font-size:0.85rem;color:var(--primary);font-weight:600;margin-bottom:8px;\">Chief Financial Officer</div>\n          <p style=\"font-size:0.85rem;margin:0;\">Chartered Accountant with experience at PwC and NAB. Passionate about sustainable finance and ESG reporting.</p>\n        </div>\n      </div>\n      <div class=\"card\">\n        <div style=\"aspect-ratio:1;background:linear-gradient(135deg,var(--primary-alpha),var(--bg-gray));display:flex;align-items:center;justify-content:center;font-size:4rem;\">👩‍💻</div>\n        <div class=\"card-body\" style=\"padding:20px;\">\n          <h4>Priya Ramanathan</h4>\n          <div style=\"font-size:0.85rem;color:var(--primary);font-weight:600;margin-bottom:8px;\">Chief Technology Officer</div>\n          <p style=\"font-size:0.85rem;margin:0;\">Ex-CTO of Afterpay. Built Australia's fastest core banking platform. PhD in Distributed Systems from UNSW.</p>\n        </div>\n      </div>\n      <div class=\"card\">\n        <div style=\"aspect-ratio:1;background:linear-gradient(135deg,var(--primary-alpha),var(--bg-gray));display:flex;align-items:center;justify-content:center;font-size:4rem;\">👨‍⚖️</div>\n        <div class=\"card-body\" style=\"padding:20px;\">\n          <h4>Robert Morrison</h4>\n          <div style=\"font-size:0.85rem;color:var(--primary);font-weight:600;margin-bottom:8px;\">Chief Risk & Compliance Officer</div>\n          <p style=\"font-size:0.85rem;margin:0;\">25 years at APRA. Led the 2018 Banking Royal Commission implementation taskforce at CBA.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section class=\"cta-section\">\n  <div class=\"container\">\n    <div class=\"cta-box\">\n      <h2>Bank with a team that cares.</h2>\n      <p>Join 250,000+ Australians who've made the switch to United Credit Bank. Open your free account in under 2 minutes.</p>\n      <a href=\"/auth/register\" class=\"btn btn-light btn-lg\">🇦🇺 Open Free Account</a>\n    </div>\n  </div>\n</section>\n\n<%- include('partials/layouts/main-end') -%>\n\n"
