var __line = 1
  , __lines = "<%- include('../partials/layouts/user-start') -%>\n\n<div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;\">\n  <div>\n    <h2 style=\"margin:0;\">🏦 My Accounts</h2>\n    <p style=\"margin:4px 0 0;color:var(--text-gray);\">All your United Credit Bank accounts in one place.</p>\n  </div>\n  <a href=\"/accounts/open/new\" class=\"btn btn-primary btn-lg\">➕ Open New Account</a>\n</div>\n\n<div class=\"grid-2\" style=\"margin-bottom:20px;\">\n  <% accounts.forEach(acc => { %>\n    <div class=\"account-card\" onclick=\"location.href='/accounts/<%= acc.id %>'\" style=\"cursor:pointer;\">\n      <div class=\"account-card-header\">\n        <div class=\"account-type\">\n          <div class=\"account-type-icon\">\n            <% if (acc.account_type.includes('High')) { %>🏆\n            <% } else if (acc.account_type.includes('Term')) { %>🔒\n            <% } else if (acc.account_type.includes('Business')) { %>🏢\n            <% } else if (acc.account_type.includes('Multi') || acc.account_type.includes('Intl')) { %>🌍\n            <% } else { %>💳<% } %>\n          </div>\n          <div>\n            <div class=\"account-name\"><%= acc.account_type %></div>\n            <div class=\"account-number\">BSB <%= acc.bsb %> • <%= acc.account_number %></div>\n          </div>\n        </div>\n        <div class=\"account-balance\">\n          <div class=\"account-balance-label\">Available</div>\n          <div class=\"account-balance-value\"><%= currency(acc.available_balance) %></div>\n          <div style=\"font-size:0.8rem;color:var(--text-light);text-align:right;\">Balance: <%= currency(acc.balance) %></div>\n        </div>\n      </div>\n      <div class=\"account-meta\">\n        <div class=\"account-meta-item\">\n          <span class=\"account-meta-label\">Branch</span>\n          <span class=\"account-meta-value\"><%= acc.branch %></span>\n        </div>\n        <div class=\"account-meta-item\">\n          <span class=\"account-meta-label\">Opened</span>\n          <span class=\"account-meta-value\"><%= moment(acc.opened_date).format('DD MMM YYYY') %></span>\n        </div>\n        <div class=\"account-meta-item\">\n          <span class=\"account-meta-label\">Status</span>\n          <span class=\"status-badge status-<%= acc.status %>\"><%= acc.status %></span>\n        </div>\n      </div>\n      <div class=\"account-actions\" onclick=\"event.stopPropagation();\">\n        <a href=\"/accounts/<%= acc.id %>\" class=\"btn btn-light btn-sm\">Details</a>\n        <a href=\"/transfers/local?from=<%= acc.id %>\" class=\"btn btn-outline btn-sm\">Transfer</a>\n        <a href=\"/user/statements?account=<%= acc.id %>\" class=\"btn btn-light btn-sm\">Statement</a>\n        <% if (parseFloat(acc.balance) === 0 && acc.status === 'active') { %>\n          <form method=\"POST\" action=\"/accounts/<%= acc.id %>/close\" style=\"display:inline;\" onsubmit=\"return confirm('Close this account?');\">\n            <button class=\"btn btn-danger btn-sm\" type=\"submit\">Close</button>\n          </form>\n        <% } %>\n      </div>\n    </div>\n  <% }) %>\n</div>\n\n<% if (accounts.length === 0) { %>\n  <div class=\"card\">\n    <div class=\"card-body\">\n      <div class=\"empty-state\">\n        <div class=\"empty-state-icon\">🏦</div>\n        <h4>No accounts yet</h4>\n        <p>Open your first account with United Credit Bank today — it takes less than 2 minutes.</p>\n        <a href=\"/accounts/open/new\" class=\"btn btn-primary btn-lg\" style=\"margin-top:16px;\">🚀 Open Your First Account</a>\n      </div>\n    </div>\n  </div>\n<% } %>\n\n<%- include('../partials/layouts/user-end') -%>\n\n\n"
