var __line = 1
  , __lines = "<%- include('../partials/layouts/admin-start') -%>\n\n<h2 style=\"margin-bottom:16px;\">Manage Cards <span style=\"font-size:0.85rem;color:var(--text-light);\">(latest 200)</span></h2>\n<div class=\"alert alert-info\" style=\"margin-bottom:20px;\"><span class=\"alert-icon\">i</span><div class=\"alert-content\"><div class=\"alert-title\">Issuer boundary</div><p class=\"alert-message\" style=\"margin:0;\">Pending applications can be approved or rejected in the approval queue. Approval is not card issuance; no issuer is connected. Active cards may be frozen, blocked, or marked lost/stolen with a reason. Full card number, CVV, and PIN hash are never rendered here.</p></div></div>\n\n<div class=\"card\">\n  <form class=\"filter-bar\" method=\"GET\" action=\"/admin/cards\">\n    <div class=\"filter-group\"><label class=\"filter-label\" for=\"cardSearch\">Search</label><input type=\"text\" id=\"cardSearch\" name=\"search\" value=\"<%= filters.search || '' %>\" class=\"form-input\" placeholder=\"Cardholder, last 4 digits...\"></div>\n    <div class=\"filter-group\"><span class=\"filter-label\">Type</span>\n      <select class=\"form-select\" name=\"type\"><option value=\"all\">All</option><option value=\"Debit\" <%= filters.type === 'Debit' ? 'selected' : '' %>>Debit</option><option value=\"Credit\" <%= filters.type === 'Credit' ? 'selected' : '' %>>Credit</option></select>\n    </div>\n    <div class=\"filter-group\"><span class=\"filter-label\">Status</span>\n      <select class=\"form-select\" name=\"status\">\n        <option value=\"all\">All</option><% ['pending','awaiting_issuer','approved','active','frozen','blocked','lost_stolen','rejected'].forEach(s=>{ %><option value=\"<%= s %>\" <%= filters.status === s ? 'selected' : '' %>><%= s.replace('_',' / ') %></option><% }) %>\n      </select>\n    </div>\n    <button class=\"btn btn-primary btn-sm\">Filter</button>\n  </form>\n  <div class=\"table-wrap\">\n    <table class=\"table\">\n      <thead><tr><th>Cardholder</th><th>Card Type</th><th>Last 4</th><th style=\"text-align:right;\">Limit</th><th>Expiry</th><th>Status</th><th>Actions</th></tr></thead>\n      <tbody>\n        <% cards.forEach(c => { const canManage = ['approved','awaiting_issuer','active','frozen'].includes(String(c.status)); const canActivate = c.fulfillment_status === 'issued'; %>\n          <tr>\n            <td><div style=\"display:flex;gap:8px;align-items:center;\">\n              <div class=\"user-avatar\" style=\"width:32px;height:32px;font-size:0.75rem;\"><%= (c.cardholder_name||c.user_name||'?').charAt(0) %></div>\n              <div><div style=\"font-weight:600;font-size:0.88rem;\"><%= c.user_name || c.cardholder_name || 'User #' + c.user_id %></div>\n                <div style=\"font-size:0.72rem;color:var(--text-light);\"><%= c.cardholder_name %></div></div></div></td>\n            <td><strong style=\"font-size:0.85rem;\"><%= c.card_type %></strong></td>\n            <td style=\"font-family:monospace;\">•••• <%= c.card_last4 || (c.card_number||'').slice(-4) || '—' %></td>\n            <td style=\"text-align:right;font-weight:700;\"><%= currency(c.credit_limit || 0) %></td>\n            <td><%= c.expiry_date || 'MM/YY' %></td>\n            <td><span class=\"status-badge status-<%= c.status %>\"><%= c.status %></span></td>\n            <td>\n              <% if (c.status === 'pending') { %><a class=\"btn btn-primary btn-sm\" href=\"/admin/approvals?section=cards\">Review application</a>\n              <% } else if (canManage) { %>\n                <form method=\"POST\" action=\"/admin/cards/<%= encodeURIComponent(c.id) %>/status\" style=\"display:flex;gap:6px;align-items:center;flex-wrap:wrap;\">\n                  <select name=\"status\" class=\"form-select\" required aria-label=\"Card status\"><% (c.status==='frozen'?(canActivate?['active','blocked','lost_stolen']:['blocked','lost_stolen']):['frozen','blocked','lost_stolen']).forEach(s=>{ %><option value=\"<%= s %>\"><%= s.replace('_',' / ') %></option><% }) %></select>\n                  <input name=\"reason\" class=\"form-input\" required minlength=\"8\" maxlength=\"500\" placeholder=\"Reason\" aria-label=\"Reason for card status change\" style=\"max-width:180px;\">\n                  <button type=\"submit\" class=\"btn btn-warning btn-sm\">Save</button>\n                </form>\n              <% } else { %><span class=\"status-badge\">No status transition available</span><% } %>\n            </td>\n          </tr>\n        <% }) %>\n      </tbody>\n    </table>\n  </div>\n</div>\n\n<%- include('../partials/layouts/admin-end') -%>\n"
