var __line = 1
  , __lines = "<%- include('../partials/layouts/admin-start') -%>\n\n<h2 style=\"margin-bottom:16px;\">📊 Reports & Analytics</h2>\n<div class=\"alert alert-info\" style=\"margin-bottom:20px;\"><span class=\"alert-icon\">i</span><div class=\"alert-content\"><div class=\"alert-title\">Real Firestore data · bounded report window</div><p class=\"alert-message\" style=\"margin:0;\">This page uses the latest up to 1,000 documents per collection. If a collection exceeds that window, these summaries are partial and should not be treated as a complete financial statement. No projected or synthetic trend figures are shown.</p></div></div>\n\n<div class=\"stat-cards\" style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:24px;\">\n  <div class=\"stat-card\">\n    <div class=\"stat-header\">\n      <div><div class=\"stat-label\">30-day Revenue</div>\n      <div class=\"stat-value\"><%= currency(revenue) %></div></div>\n      <div class=\"stat-icon stat-icon-primary\">📈</div>\n    </div><div class=\"stat-change\">Completed transaction fees in the latest 30 days</div>\n  </div>\n  <div class=\"stat-card\">\n    <div class=\"stat-header\"><div>\n      <div class=\"stat-label\">New Signups (30d)</div>\n      <div class=\"stat-value\"><%= (monthlyData.reduce((s,m)=>s+m.new_customers,0)).toLocaleString() %></div></div>\n      <div class=\"stat-icon stat-icon-success\">👥</div>\n    </div><div class=\"stat-change\">Recorded customer profiles in the latest 12 months</div>\n  </div>\n  <div class=\"stat-card\">\n    <div class=\"stat-header\"><div>\n      <div class=\"stat-label\">Deposits (30d)</div>\n      <div class=\"stat-value\"><%= currency(deposits30d) %></div></div>\n      <div class=\"stat-icon stat-icon-success\">⬇️</div>\n    </div><div class=\"stat-change\">Completed deposits in the latest 30 days</div>\n  </div>\n  <div class=\"stat-card\">\n    <div class=\"stat-header\"><div>\n      <div class=\"stat-label\">Active Loans</div>\n      <div class=\"stat-value\" style=\"color:var(--warning);\"><%= currency(loanTotals.total_outstanding) %></div></div>\n      <div class=\"stat-icon stat-icon-warning\">🏦</div>\n    </div><div class=\"stat-change\"><%= loanTotals.count %> loans</div>\n  </div>\n</div>\n\n<div class=\"grid-2\" style=\"margin-bottom:24px;\">\n  <div class=\"card\">\n    <div class=\"card-header\"><h3 class=\"card-title\">📈 Last 12 Months Performance</h3></div>\n    <div class=\"card-body\">\n      <div class=\"chart\" style=\"height:240px;display:flex;align-items:end;gap:8px;padding-top:20px;\">\n        <% monthlyData.forEach(m => {\n          const h = 100;\n          const max = Math.max(...monthlyData.map(x => x.deposits + x.withdrawals)) || 1;\n          const depH = (m.deposits / max) * h;\n          const withH = (m.withdrawals / max) * h;\n        %>\n          <div style=\"flex:1;display:flex;flex-direction:column;align-items:center;gap:4px;\">\n            <div style=\"width:100%;display:flex;gap:2px;align-items:end;height:200px;\">\n              <div style=\"flex:1;background:var(--success);border-radius:6px 6px 0 0;min-height:4px;height:<%= depH %>px;transition:var(--transition);\" title=\"Dep <%= currency(m.deposits) %>\"></div>\n              <div style=\"flex:1;background:var(--danger);border-radius:6px 6px 0 0;min-height:4px;height:<%= withH %>px;transition:var(--transition);\" title=\"With <%= currency(m.withdrawals) %>\"></div>\n            </div>\n            <div style=\"font-size:0.7rem;color:var(--text-light);font-weight:600;\"><%= m.month %></div>\n          </div>\n        <% }) %>\n      </div>\n      <div style=\"display:flex;justify-content:center;gap:20px;margin-top:10px;\">\n        <div style=\"display:flex;align-items:center;gap:6px;\"><span style=\"width:10px;height:10px;background:var(--success);border-radius:2px;\"></span><span style=\"font-size:0.82rem;color:var(--text-gray);\">Deposits</span></div>\n        <div style=\"display:flex;align-items:center;gap:6px;\"><span style=\"width:10px;height:10px;background:var(--danger);border-radius:2px;\"></span><span style=\"font-size:0.82rem;color:var(--text-gray);\">Withdrawals</span></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <div class=\"card-header\"><h3 class=\"card-title\">💸 Transaction Type Breakdown (30 days)</h3></div>\n    <div class=\"card-body\" style=\"padding:0;\">\n      <% typeBreakdown.forEach(t => { \n        const pct = (t.count / Math.max(1, typeBreakdown.reduce((s,x)=>s+x.count,0)) * 100).toFixed(1);\n      %>\n        <div style=\"padding:14px 20px;border-bottom:1px solid var(--border);\">\n          <div style=\"display:flex;justify-content:space-between;margin-bottom:6px;\">\n            <div style=\"font-weight:600;font-size:0.9rem;display:flex;align-items:center;gap:8px;\">\n              <%= t.type.includes('local')?'🇦🇺':t.type.includes('intl')?'🌍':t.type.includes('dep')?'⬇️':t.type.includes('with')?'⬆️':t.type.includes('bill')?'📄':t.type.includes('loan')?'💳':'💸' %>\n              <%= t.type.replace(/_/g,' ').replace(/\\b\\w/g, l => l.toUpperCase()) %>\n            </div>\n            <div style=\"text-align:right;\">\n              <div style=\"font-weight:800;\"><%= currency(t.total) %></div>\n              <div style=\"font-size:0.72rem;color:var(--text-light);\"><%= t.count %> tx</div>\n            </div>\n          </div>\n          <div class=\"progress\"><div class=\"progress-bar\" style=\"width:<%= pct %>%;\"></div></div>\n        </div>\n      <% }) %>\n    </div>\n  </div>\n</div>\n\n<div class=\"grid-2\">\n  <div class=\"card\">\n    <div class=\"card-header\"><h3 class=\"card-title\">🏦 Accounts Summary by Type</h3></div>\n    <div class=\"card-body\" style=\"padding:0;\">\n      <% accountSummary.forEach(a => { %>\n        <div style=\"padding:14px 20px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;\">\n          <div><div style=\"font-weight:700;\"><%= a.type %></div>\n            <div style=\"font-size:0.78rem;color:var(--text-light);\"><%= a.count %> accounts</div></div>\n          <div style=\"text-align:right;\">\n            <div style=\"font-weight:800;color:var(--primary);\"><%= currency(a.total_balance) %></div>\n            <div style=\"font-size:0.78rem;color:var(--text-light);\">Avg: <%= currency(a.count?a.total_balance/a.count:0) %></div>\n          </div>\n        </div>\n      <% }) %>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <div class=\"card-header\"><h3 class=\"card-title\">🏦 Loan Summary by Type</h3></div>\n    <div class=\"card-body\" style=\"padding:0;\">\n      <% loanSummary.forEach(l => { %>\n        <div style=\"padding:14px 20px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;\">\n          <div><div style=\"font-weight:700;\"><%= l.type %></div>\n            <div style=\"font-size:0.78rem;color:var(--text-light);\"><%= l.count %> active • Avg <%= parseFloat(l.avg_rate).toFixed(2) %>%</div></div>\n          <div style=\"text-align:right;\">\n            <div style=\"font-weight:800;color:var(--warning);\"><%= currency(l.outstanding) %></div>\n            <div style=\"font-size:0.78rem;color:var(--text-light);\">Mo: <%= currency(l.monthly_total) %></div>\n          </div>\n        </div>\n      <% }) %>\n    </div>\n  </div>\n</div>\n\n<%- include('../partials/layouts/admin-end') -%>\n\n"
