var __line = 1
  , __lines = "<!DOCTYPE html>\n<html lang=\"en-AU\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <meta name=\"theme-color\" content=\"#C8102E\">\n  <title><%= title %></title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n  <link rel=\"stylesheet\" href=\"/css/style.css\">\n  <link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect width='100' height='100' rx='20' fill='%23C8102E'/><text x='50' y='62' font-size='48' font-family='Arial' font-weight='800' text-anchor='middle' fill='white'>U</text></svg>\">\n</head>\n<body class=\"auth-wrap\">\n  <div class=\"auth-card\" style=\"max-width:760px;\">\n    <div class=\"auth-header\">\n      <div style=\"display:flex;align-items:center;justify-content:center;gap:12px;margin-bottom:16px;\">\n        <div class=\"brand-logo\">UCB</div>\n        <div style=\"text-align:left;\">\n          <div style=\"font-weight:800;color:var(--text-dark);font-size:1.1rem;\">United Credit Bank</div>\n          <div style=\"font-size:0.75rem;color:var(--text-light);\">🇦🇺 Open an account in under 2 minutes</div>\n        </div>\n      </div>\n      <h1 style=\"font-size:1.6rem;\">Open your free Australian bank account</h1>\n      <p>No monthly fees, no minimum balance, full digital banking access.</p>\n    </div>\n\n    <% if (typeof errors !== 'undefined' && errors && errors.length > 0) { %>\n      <div class=\"form-alert form-alert-error\">\n        <strong>⚠️ Please check the following:</strong>\n        <ul style=\"margin-top:6px;padding-left:18px;\">\n          <% errors.forEach(e => { %>\n            <li><%= e.msg %></li>\n          <% }) %>\n        </ul>\n      </div>\n    <% } %>\n    <% if (typeof error !== 'undefined' && error) { %>\n      <div class=\"form-alert form-alert-error\">⚠️ <%= error %></div>\n    <% } %>\n\n    <form action=\"/auth/register\" method=\"POST\" id=\"registerForm\">\n      <div class=\"form-grid\">\n        <div class=\"form-group\">\n          <label class=\"form-label\">First Name *</label>\n          <input type=\"text\" name=\"first_name\" class=\"form-input\" value=\"<%= typeof old !== 'undefined' ? old.first_name || '' : '' %>\" required placeholder=\"John\">\n        </div>\n        <div class=\"form-group\">\n          <label class=\"form-label\">Last Name *</label>\n          <input type=\"text\" name=\"last_name\" class=\"form-input\" value=\"<%= typeof old !== 'undefined' ? old.last_name || '' : '' %>\" required placeholder=\"Smith\">\n        </div>\n      </div>\n      <div class=\"form-grid\">\n        <div class=\"form-group\">\n          <label class=\"form-label\">Email Address *</label>\n          <input type=\"email\" name=\"email\" class=\"form-input\" value=\"<%= typeof old !== 'undefined' ? old.email || '' : '' %>\" required placeholder=\"you@example.com.au\">\n        </div>\n        <div class=\"form-group\">\n          <label class=\"form-label\">Phone Number *</label>\n          <input type=\"tel\" name=\"phone\" class=\"form-input\" value=\"<%= typeof old !== 'undefined' ? old.phone || '' : '' %>\" required placeholder=\"0412 345 678\">\n        </div>\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Date of Birth</label>\n        <input type=\"date\" name=\"date_of_birth\" class=\"form-input\" value=\"<%= typeof old !== 'undefined' ? old.date_of_birth || '' : '' %>\" max=\"2010-01-01\">\n        <span class=\"form-hint\">Required for KYC verification later</span>\n      </div>\n      <div class=\"form-grid\">\n        <div class=\"form-group\">\n          <label class=\"form-label\">Street Address</label>\n          <input type=\"text\" name=\"address\" class=\"form-input\" value=\"<%= typeof old !== 'undefined' ? old.address || '' : '' %>\" placeholder=\"123 Main Street\">\n        </div>\n        <div class=\"form-group\">\n          <label class=\"form-label\">Suburb / City</label>\n          <input type=\"text\" name=\"city\" class=\"form-input\" value=\"<%= typeof old !== 'undefined' ? old.city || '' : '' %>\" placeholder=\"Sydney\">\n        </div>\n      </div>\n      <div class=\"form-grid\">\n        <div class=\"form-group\">\n          <label class=\"form-label\">State</label>\n          <select name=\"state\" class=\"form-select\">\n            <option value=\"\">Select State</option>\n            <option value=\"NSW\" <%= (typeof old !== 'undefined' && old.state === 'NSW') ? 'selected' : '' %>>NSW - New South Wales</option>\n            <option value=\"VIC\" <%= (typeof old !== 'undefined' && old.state === 'VIC') ? 'selected' : '' %>>VIC - Victoria</option>\n            <option value=\"QLD\" <%= (typeof old !== 'undefined' && old.state === 'QLD') ? 'selected' : '' %>>QLD - Queensland</option>\n            <option value=\"SA\" <%= (typeof old !== 'undefined' && old.state === 'SA') ? 'selected' : '' %>>SA - South Australia</option>\n            <option value=\"WA\" <%= (typeof old !== 'undefined' && old.state === 'WA') ? 'selected' : '' %>>WA - Western Australia</option>\n            <option value=\"TAS\" <%= (typeof old !== 'undefined' && old.state === 'TAS') ? 'selected' : '' %>>TAS - Tasmania</option>\n            <option value=\"ACT\" <%= (typeof old !== 'undefined' && old.state === 'ACT') ? 'selected' : '' %>>ACT - Australian Capital</option>\n            <option value=\"NT\" <%= (typeof old !== 'undefined' && old.state === 'NT') ? 'selected' : '' %>>NT - Northern Territory</option>\n          </select>\n        </div>\n        <div class=\"form-group\">\n          <label class=\"form-label\">Postcode</label>\n          <input type=\"text\" name=\"postcode\" class=\"form-input\" value=\"<%= typeof old !== 'undefined' ? old.postcode || '' : '' %>\" placeholder=\"2000\">\n        </div>\n      </div>\n      <div class=\"form-grid\">\n        <div class=\"form-group\">\n          <label class=\"form-label\">Password *</label>\n          <input type=\"password\" name=\"password\" class=\"form-input\" id=\"regPwd\" required placeholder=\"At least 8 characters\">\n          <span class=\"form-hint\">Minimum 8 characters, include numbers & letters</span>\n        </div>\n        <div class=\"form-group\">\n          <label class=\"form-label\">Confirm Password *</label>\n          <input type=\"password\" name=\"confirm_password\" class=\"form-input\" id=\"regPwdConfirm\" required placeholder=\"Re-enter password\">\n          <div id=\"pwdMatch\"></div>\n        </div>\n      </div>\n      <div style=\"padding:16px;background:var(--primary-alpha);border-radius:var(--radius-sm);margin-bottom:20px;border:1px solid rgba(200,16,46,0.15);\">\n        <label style=\"display:flex;align-items:flex-start;gap:10px;cursor:pointer;font-size:0.9rem;color:var(--text-dark);\">\n          <input type=\"checkbox\" name=\"terms\" required style=\"width:18px;height:18px;margin-top:2px;\">\n          <div>\n            <strong>I agree to the United Credit Bank Terms & Conditions</strong>\n            <div style=\"color:var(--text-gray);font-size:0.8rem;margin-top:2px;\">I confirm I am 18+ years old, an Australian resident for tax purposes, and consent to electronic communications.</div>\n          </div>\n        </label>\n      </div>\n      <button type=\"submit\" class=\"btn btn-primary btn-lg btn-block\">🇦🇺 Open My Free Account</button>\n    </form>\n\n    <div class=\"auth-footer\">\n      Already have an account? <a href=\"/auth/login\" style=\"font-weight:600;\">Sign in here</a>\n    </div>\n  </div>\n  <script src=\"/js/common.js\"></script>\n  <script src=\"/js/auth.js\"></script>\n</body>\n</html>\n"
