var __line = 1
  , __lines = "<%- include('../partials/layouts/user-start') -%>\n\n<a href=\"/billpay\" class=\"btn btn-outline btn-sm\" style=\"margin-bottom:16px;\">← Bills Hub</a>\n\n<div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;flex-wrap:wrap;gap:12px;\">\n  <div>\n    <h2 style=\"margin:0;\">📅 Scheduled Payments</h2>\n    <p style=\"margin:4px 0 0;color:var(--text-gray);\">Recurring and future-dated bill payments.</p>\n  </div>\n  <a href=\"/billpay/pay\" class=\"btn btn-primary\">➕ Schedule Payment</a>\n</div>\n\n<div class=\"card\">\n  <div class=\"filter-bar\">\n    <div class=\"filter-group\">\n      <span class=\"filter-label\">Status</span>\n      <select class=\"form-select\">\n        <option>All</option>\n        <option>Scheduled</option>\n        <option>Completed</option>\n        <option>Cancelled</option>\n        <option>Failed</option>\n      </select>\n    </div>\n    <button class=\"btn btn-primary btn-sm\">🔍 Filter</button>\n  </div>\n\n  <div class=\"table-wrap\">\n    <table class=\"table\">\n      <thead>\n        <tr>\n          <th>Scheduled Date</th>\n          <th>Biller</th>\n          <th>Reference</th>\n          <th>Frequency</th>\n          <th style=\"text-align:right;\">Amount</th>\n          <th>Status</th>\n          <th>Actions</th>\n        </tr>\n      </thead>\n      <tbody>\n        <% const sched = upcoming.filter(b => b.status === 'scheduled' || b.status === 'pending'); %>\n        <% if (sched.length === 0) { %>\n          <tr><td colspan=\"7\"><div class=\"empty-state\" style=\"padding:60px 20px;\"><div class=\"empty-state-icon\" style=\"width:72px;height:72px;font-size:2.2rem;\">📅</div><h4>No scheduled payments</h4><p>Set up recurring payments to ensure you never miss a bill.</p></div></td></tr>\n        <% } %>\n        <% sched.forEach(b => { %>\n          <tr>\n            <td>\n              <div style=\"font-weight:600;\"><%= moment(b.due_date || b.scheduled_date || b.created_at).format('DD MMM YYYY') %></div>\n              <div style=\"font-size:0.75rem;color:var(--text-light);\"><%= moment(b.due_date || b.scheduled_date || b.created_at).fromNow() %></div>\n            </td>\n            <td>\n              <div style=\"font-weight:600;font-size:0.9rem;\"><%= b.biller_name || b.description || 'Payment' %></div>\n              <% if (b.biller_code) { %><div style=\"font-size:0.72rem;color:var(--text-light);\">BPAY Code: <%= b.biller_code %></div><% } %>\n            </td>\n            <td style=\"font-family:monospace;font-size:0.85rem;\"><%= b.customer_ref || '—' %></td>\n            <td><span class=\"tag tag-verified\"><%= b.frequency || 'One-off' %></span></td>\n            <td style=\"text-align:right;font-weight:700;color:var(--danger);\">-<%= currency(b.amount) %></td>\n            <td><span class=\"status-badge status-<%= b.status %>\"><%= b.status %></span></td>\n            <td>\n              <a href=\"/billpay/<%= b.id %>\" class=\"btn btn-light btn-sm\">View</a>\n              <% if (b.status === 'scheduled' || b.status === 'pending') { %>\n                <form method=\"POST\" action=\"/billpay/<%= b.id %>/cancel\" style=\"display:inline;\" onsubmit=\"return confirm('Cancel this scheduled payment?');\">\n                  <button class=\"btn btn-danger btn-sm\">Cancel</button>\n                </form>\n              <% } %>\n            </td>\n          </tr>\n        <% }) %>\n      </tbody>\n    </table>\n  </div>\n</div>\n\n<%- include('../partials/layouts/user-end') -%>\n\n\n"
