var __line = 1
  , __lines = "<% const pageScripts = ['/js/cards.js']; %>\n<%- include('../partials/layouts/user-start') -%>\n\n<a href=\"/cards\" class=\"btn btn-outline btn-sm\" style=\"margin-bottom:16px;\">← All Cards</a>\n\n<div class=\"section-header\" style=\"text-align:left;margin-bottom:24px;\">\n  <span class=\"section-eyebrow\">💳 Apply for Card</span>\n  <h2 style=\"font-size:2rem;margin:12px 0 8px;\">Get your new card today</h2>\n  <p style=\"margin:0;\">Applications typically approved within 1 business day for verified customers.</p>\n</div>\n\n<div class=\"grid-2\">\n  <div class=\"card\">\n    <div class=\"card-header\"><h3 class=\"card-title\">📝 Application Form</h3></div>\n    <div class=\"card-body\">\n      <form method=\"POST\" action=\"/cards/apply\">\n        <div class=\"form-group\">\n          <label class=\"form-label\">Select Card Type *</label>\n          <select name=\"card_type\" required class=\"form-select\" id=\"cardTypeSelect\" onchange=\"updateCardSummary()\">\n            <% cardTypes.forEach((c, i) => { %>\n              <option value=\"<%= c.type %>\" data-fee=\"<%= c.fee_raw || 0 %>\" data-limit=\"<%= c.limit_raw || 5000 %>\" <%= (typeof selectedCardType !== 'undefined' && selectedCardType === c.type) ? 'selected' : '' %>>\n                <%= c.name %> • <%= c.type.includes('Credit') ? c.interest : c.fee %>\n              </option>\n            <% }) %>\n          </select>\n        </div>\n\n        <div class=\"form-grid\">\n          <div class=\"form-group\">\n            <label class=\"form-label\">Title</label>\n            <select name=\"title\" class=\"form-select\">\n              <option>Mr</option><option>Mrs</option><option>Ms</option>\n              <option>Dr</option><option>Prof</option>\n            </select>\n          </div>\n          <div class=\"form-group\">\n            <label class=\"form-label\">Preferred Name on Card *</label>\n            <input type=\"text\" name=\"cardholder_name\" required class=\"form-input\" maxlength=\"22\" placeholder=\"e.g. JOHN SMITH\" value=\"<%= user.first_name.toUpperCase() %> <%= user.last_name.toUpperCase() %>\">\n            <span class=\"form-hint\">Max 22 characters, uppercase</span>\n          </div>\n        </div>\n\n        <div class=\"form-group\">\n          <label class=\"form-label\">Link to Account (for Debit) *</label>\n          <select name=\"account_id\" required class=\"form-select\">\n            <% accounts.forEach(acc => { %>\n              <option value=\"<%= acc.id %>\"><%= acc.account_type %> • BSB <%= acc.bsb %> • <%= currency(acc.balance) %></option>\n            <% }) %>\n          </select>\n        </div>\n\n        <% if (!user.is_verified) { %>\n          <div class=\"alert alert-warning\" style=\"margin-bottom:20px;\">\n            <span class=\"alert-icon\">⚠️</span>\n            <div class=\"alert-content\">\n              <div class=\"alert-title\">KYC Verification Required</div>\n              <p class=\"alert-message\" style=\"margin:0;\">Your card application will require KYC verification before approval.\n                <a href=\"/kyc/submit\" style=\"color:var(--primary);font-weight:700;\">Complete KYC now →</a>\n              </p>\n            </div>\n          </div>\n        <% } %>\n\n        <div class=\"form-grid\">\n          <div class=\"form-group\">\n            <label class=\"form-label\">Employment Status</label>\n            <select name=\"employment\" class=\"form-select\">\n              <option value=\"employed\">Full-time Employed</option>\n              <option value=\"part_time\">Part-time</option>\n              <option value=\"casual\">Casual</option>\n              <option value=\"self_employed\">Self-Employed</option>\n              <option value=\"retired\">Retired</option>\n              <option value=\"student\">Student</option>\n            </select>\n          </div>\n          <div class=\"form-group\">\n            <label class=\"form-label\">Annual Income (AUD)</label>\n            <input type=\"number\" name=\"income\" min=\"0\" class=\"form-input\" placeholder=\"e.g. 75000\">\n          </div>\n        </div>\n\n        <div class=\"form-group\">\n          <label class=\"form-label\">Requested Credit Limit (Credit cards only)</label>\n          <select name=\"credit_limit\" class=\"form-select\">\n            <option value=\"\">— Use default —</option>\n            <option value=\"2000\">$2,000</option>\n            <option value=\"5000\">$5,000</option>\n            <option value=\"10000\">$10,000</option>\n            <option value=\"15000\">$15,000</option>\n            <option value=\"25000\">$25,000</option>\n            <option value=\"50000\">$50,000</option>\n          </select>\n        </div>\n\n        <div class=\"alert alert-info\" style=\"margin-bottom:20px;\">\n          <span class=\"alert-icon\">ℹ️</span>\n          <div class=\"alert-content\">\n            <div class=\"alert-title\">Card Delivery</div>\n            <p class=\"alert-message\" style=\"margin:0;\">Digital card available instantly in app. Physical card mailed to your address within 3-5 business days (metro Australia).</p>\n          </div>\n        </div>\n\n        <button type=\"submit\" class=\"btn btn-primary btn-lg btn-block\">✅ Submit Application</button>\n      </form>\n    </div>\n  </div>\n\n  <div>\n    <div class=\"card\" style=\"margin-bottom:20px;\">\n      <div class=\"card-header\"><h3 class=\"card-title\">💳 Preview Card</h3></div>\n      <div class=\"card-body\">\n        <div id=\"cardPreview\" style=\"position:relative;border-radius:20px;padding:24px;color:white;background:linear-gradient(135deg,#C8102E,#7A0A1D);overflow:hidden;min-height:210px;\">\n          <div style=\"position:absolute;top:-40px;right:-40px;width:180px;height:180px;background:white;opacity:0.06;border-radius:50%;\"></div>\n          <div style=\"position:relative;z-index:1;display:flex;justify-content:space-between;align-items:start;\">\n            <div>\n              <div style=\"font-size:0.7rem;opacity:0.75;text-transform:uppercase;letter-spacing:0.1em;\">United Credit Bank</div>\n              <div style=\"font-weight:700;font-size:1.05rem;margin-top:4px;\" id=\"previewCardType\"><%= cardTypes[0].name %></div>\n            </div>\n            <div style=\"font-size:0.7rem;background:rgba(255,255,255,0.15);padding:4px 10px;border-radius:999px;font-weight:700;\">\n              <%= user.is_verified ? '● INSTANT APPROVAL' : '⏳ REVIEW' %>\n            </div>\n          </div>\n          <div style=\"position:relative;z-index:1;margin-top:24px;\">\n            <div style=\"display:flex;gap:10px;align-items:center;\">\n              <div style=\"width:36px;height:28px;background:linear-gradient(135deg,#FCD34D,#F59E0B);border-radius:4px;\"></div>\n              <div style=\"margin-left:auto;font-weight:800;font-style:italic;opacity:0.9;\">VISA</div>\n            </div>\n            <div style=\"font-family:monospace;font-size:1.15rem;margin-top:16px;letter-spacing:0.05em;font-weight:600;\">4539 •••• •••• ####</div>\n          </div>\n          <div style=\"position:relative;z-index:1;margin-top:18px;display:flex;justify-content:space-between;align-items:end;\">\n            <div>\n              <div style=\"font-size:0.6rem;opacity:0.7;text-transform:uppercase;letter-spacing:0.05em;\">Cardholder</div>\n              <div style=\"font-weight:600;font-size:0.95rem;\"><%= user.first_name.toUpperCase() %> <%= user.last_name.toUpperCase() %></div>\n            </div>\n            <div style=\"text-align:right;\">\n              <div style=\"font-size:0.6rem;opacity:0.7;text-transform:uppercase;letter-spacing:0.05em;\">Exp</div>\n              <div style=\"font-family:monospace;font-weight:600;\"><%= moment().add(4, 'years').format('MM/YY') %></div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-header\"><h3 class=\"card-title\">📋 Application Summary</h3></div>\n      <div class=\"card-body\" id=\"applySummaryBox\" style=\"padding:0;\">\n        <div style=\"display:flex;justify-content:space-between;padding:14px 20px;border-bottom:1px solid var(--border);\">\n          <span style=\"color:var(--text-gray);\">Annual fee</span>\n          <strong id=\"sumFee\"><%= cardTypes[0].fee %></strong>\n        </div>\n        <div style=\"display:flex;justify-content:space-between;padding:14px 20px;border-bottom:1px solid var(--border);\">\n          <span style=\"color:var(--text-gray);\">Default limit</span>\n          <strong id=\"sumLimit\"><%= cardTypes[0].limit %></strong>\n        </div>\n        <div style=\"display:flex;justify-content:space-between;padding:14px 20px;border-bottom:1px solid var(--border);\">\n          <span style=\"color:var(--text-gray);\">Digital card</span>\n          <strong style=\"color:var(--success);\">✓ Instant</strong>\n        </div>\n        <div style=\"display:flex;justify-content:space-between;padding:14px 20px;border-bottom:1px solid var(--border);\">\n          <span style=\"color:var(--text-gray);\">Physical card</span>\n          <strong>3-5 business days</strong>\n        </div>\n        <div style=\"display:flex;justify-content:space-between;padding:14px 20px;\">\n          <span style=\"color:var(--text-gray);\">Est. decision</span>\n          <strong style=\"color:<%= user.is_verified ? 'var(--success)' : 'var(--warning)' %>;\"><%= user.is_verified ? 'Same day' : 'After KYC' %></strong>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\nfunction updateCardSummary() {\n  const sel = document.getElementById('cardTypeSelect');\n  const opts = sel.selectedOptions[0];\n  document.getElementById('previewCardType').textContent = sel.textContent.split(' • ')[0];\n}\n</script>\n\n<%- include('../partials/layouts/user-end', { pageScripts }) -%>\n\n\n"
