var __line = 1
  , __lines = "<% const pageScripts = ['/js/cards.js']; %>\n<%- include('../partials/layouts/user-start') -%>\n\n<a href=\"/cards\" class=\"btn btn-outline btn-sm\" style=\"margin-bottom:16px;\">← All Cards</a>\n\n<% \n  const num = card.card_number || '4539000000000000';\n  const masked = num.slice(0,4) + ' ' + '•••• ' + '•••• ' + num.slice(-4);\n  const isCredit = card.card_type.includes('Credit');\n  const statusColor = card.status === 'active' ? 'var(--success-light)' : card.status === 'pending' ? 'var(--warning-light)' : 'var(--danger-light)';\n  const statusTextColor = card.status === 'active' ? 'var(--success)' : card.status === 'pending' ? 'var(--warning)' : 'var(--danger)';\n%>\n\n<div style=\"display:grid;grid-template-columns:380px 1fr;gap:24px;margin-bottom:24px;\">\n  <div style=\"position:relative;border-radius:24px;padding:28px;color:white;background:<%= card.status === 'blocked' || card.is_lost ? 'linear-gradient(135deg,#4B5563,#1F2937)' : isCredit ? 'linear-gradient(135deg,#C8102E,#7A0A1D)' : 'linear-gradient(135deg,#111827,#374151)' %>;overflow:hidden;min-height:240px;aspect-ratio:1.586;\">\n    <div style=\"position:absolute;top:-50px;right:-50px;width:220px;height:220px;background:white;opacity:0.06;border-radius:50%;\"></div>\n    <div style=\"position:absolute;bottom:-40px;left:-40px;width:160px;height:160px;background:white;opacity:0.05;border-radius:50%;\"></div>\n    <div style=\"position:relative;z-index:1;display:flex;justify-content:space-between;align-items:start;\">\n      <div>\n        <div style=\"font-size:0.72rem;opacity:0.75;text-transform:uppercase;letter-spacing:0.12em;\">United Credit Bank</div>\n        <div style=\"font-weight:700;font-size:1.15rem;margin-top:4px;\"><%= card.card_type %></div>\n      </div>\n      <div style=\"padding:5px 12px;border-radius:999px;background:<%= statusColor %>;color:<%= statusTextColor %>;font-weight:700;font-size:0.7rem;text-transform:uppercase;letter-spacing:0.05em;\">\n        <%= card.status %>\n      </div>\n    </div>\n    <div style=\"position:relative;z-index:1;margin-top:36px;\">\n      <div style=\"display:flex;gap:12px;align-items:center;\">\n        <div style=\"width:44px;height:34px;background:linear-gradient(135deg,#FCD34D,#F59E0B);border-radius:5px;\"></div>\n        <% if (isCredit) { %>\n          <div style=\"margin-left:auto;font-size:1rem;font-weight:800;font-style:italic;opacity:0.9;\">VISA</div>\n        <% } else { %>\n          <div style=\"margin-left:auto;font-size:0.9rem;font-weight:800;opacity:0.9;\">eftpos ▸</div>\n        <% } %>\n      </div>\n      <div style=\"font-family:monospace;font-size:1.35rem;margin-top:22px;letter-spacing:0.08em;font-weight:600;cursor:pointer;\" onclick=\"toggleNumber()\"><%= masked %></div>\n    </div>\n    <div style=\"position:relative;z-index:1;margin-top:22px;display:flex;justify-content:space-between;align-items:end;\">\n      <div>\n        <div style=\"font-size:0.62rem;opacity:0.7;text-transform:uppercase;letter-spacing:0.06em;\">Cardholder</div>\n        <div style=\"font-weight:600;font-size:1rem;margin-top:2px;\"><%= card.cardholder_name || user.first_name + ' ' + user.last_name %></div>\n      </div>\n      <div style=\"text-align:right;\">\n        <div style=\"font-size:0.62rem;opacity:0.7;text-transform:uppercase;letter-spacing:0.06em;\">Expires</div>\n        <div style=\"font-family:monospace;font-weight:600;font-size:1rem;margin-top:2px;\"><%= card.expiry_date || 'MM/YY' %></div>\n      </div>\n    </div>\n  </div>\n\n  <div>\n    <div class=\"stat-cards\" style=\"display:grid;grid-template-columns:repeat(2,1fr);gap:16px;margin-bottom:16px;\">\n      <div class=\"stat-card\">\n        <div class=\"stat-header\">\n          <div>\n            <div class=\"stat-label\"><%= isCredit ? 'Credit Available' : 'Available Balance' %></div>\n            <div class=\"stat-value\" style=\"color:var(--success);\"><%= currency(card.available_credit || 0) %></div>\n          </div>\n          <div class=\"stat-icon stat-icon-success\">✅</div>\n        </div>\n        <div class=\"stat-change up\">of <%= currency(card.credit_limit || 0) %> limit</div>\n      </div>\n      <div class=\"stat-card\">\n        <div class=\"stat-header\">\n          <div>\n            <div class=\"stat-label\">CVV</div>\n            <div class=\"stat-value\" style=\"color:var(--primary);font-family:monospace;\">•••</div>\n          </div>\n          <div class=\"stat-icon stat-icon-primary\">🔒</div>\n        </div>\n        <div class=\"stat-change\">Tap to reveal</div>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-body\" style=\"padding:0;\">\n        <div style=\"display:flex;gap:0;border-bottom:1px solid var(--border);\">\n          <button class=\"btn btn-light\" style=\"flex:1;border-radius:0;border:none;background:var(--primary-alpha);color:var(--primary);font-weight:700;\" onclick=\"showTab('actions')\">⚡ Quick Actions</button>\n          <button class=\"btn btn-light\" style=\"flex:1;border-radius:0;border:none;background:transparent;\" onclick=\"showTab('settings')\">⚙️ Card Settings</button>\n        </div>\n        <div id=\"actionsTab\" style=\"padding:20px;display:grid;grid-template-columns:repeat(2,1fr);gap:10px;\">\n          <% if (card.status === 'active') { %>\n            <a href=\"#\" class=\"btn btn-outline\" style=\"justify-content:flex-start;\">🔢 Change PIN</a>\n            <a href=\"#\" class=\"btn btn-outline\" style=\"justify-content:flex-start;\">💳 View Card Number</a>\n            <a href=\"/cards/<%= card.id %>/freeze\" class=\"btn btn-outline\" style=\"justify-content:flex-start;\">❄️ Freeze Card</a>\n            <a href=\"/cards/<%= card.id %>/replace\" class=\"btn btn-outline\" style=\"justify-content:flex-start;\">🔄 Replace Card</a>\n          <% } %>\n          <% if (card.status === 'frozen') { %>\n            <a href=\"/cards/<%= card.id %>/unfreeze\" class=\"btn btn-primary\" style=\"justify-content:flex-start;\">🔥 Unfreeze Card</a>\n          <% } %>\n          <a href=\"/cards/<%= card.id %>/report\" onclick=\"return confirm('Report this card as lost/stolen? This will permanently block it.');\" class=\"btn btn-danger\" style=\"grid-column:span 2;justify-content:flex-start;\">🚨 Report Lost / Stolen</a>\n        </div>\n        <div id=\"settingsTab\" style=\"display:none;padding:20px;\">\n          <div style=\"display:flex;justify-content:space-between;align-items:center;padding:12px 0;border-bottom:1px solid var(--border);\">\n            <div>\n              <div style=\"font-weight:600;\">Contactless Payments</div>\n              <div style=\"font-size:0.82rem;color:var(--text-light);\">$200 limit per tap</div>\n            </div>\n            <span class=\"status-badge status-active\">Enabled</span>\n          </div>\n          <div style=\"display:flex;justify-content:space-between;align-items:center;padding:12px 0;border-bottom:1px solid var(--border);\">\n            <div>\n              <div style=\"font-weight:600;\">Online Purchases</div>\n              <div style=\"font-size:0.82rem;color:var(--text-light);\">Internet & e-commerce</div>\n            </div>\n            <span class=\"status-badge status-active\">Enabled</span>\n          </div>\n          <div style=\"display:flex;justify-content:space-between;align-items:center;padding:12px 0;border-bottom:1px solid var(--border);\">\n            <div>\n              <div style=\"font-weight:600;\">Overseas Use</div>\n              <div style=\"font-size:0.82rem;color:var(--text-light);\">International ATM/POS</div>\n            </div>\n            <span class=\"status-badge status-pending\">Disabled</span>\n          </div>\n          <div style=\"display:flex;justify-content:space-between;align-items:center;padding:12px 0;\">\n            <div>\n              <div style=\"font-weight:600;\">ATM Withdrawals</div>\n              <div style=\"font-size:0.82rem;color:var(--text-light);\">$1,000 daily limit</div>\n            </div>\n            <span class=\"status-badge status-active\">Enabled</span>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<div class=\"grid-2\">\n  <div class=\"card\">\n    <div class=\"card-header\"><h3 class=\"card-title\">📋 Card Information</h3></div>\n    <div class=\"card-body\" style=\"padding:0;\">\n      <div style=\"display:flex;justify-content:space-between;padding:14px 24px;border-bottom:1px solid var(--border);\">\n        <span style=\"color:var(--text-gray);\">Card ID</span>\n        <strong style=\"font-family:monospace;\">CARD-<%= String(card.id).padStart(6, '0') %></strong>\n      </div>\n      <div style=\"display:flex;justify-content:space-between;padding:14px 24px;border-bottom:1px solid var(--border);\">\n        <span style=\"color:var(--text-gray);\">Card Type</span>\n        <strong><%= card.card_type %></strong>\n      </div>\n      <div style=\"display:flex;justify-content:space-between;padding:14px 24px;border-bottom:1px solid var(--border);\">\n        <span style=\"color:var(--text-gray);\">Status</span>\n        <span class=\"status-badge status-<%= card.status %>\"><%= card.status %></span>\n      </div>\n      <% if (isCredit) { %>\n      <div style=\"display:flex;justify-content:space-between;padding:14px 24px;border-bottom:1px solid var(--border);\">\n        <span style=\"color:var(--text-gray);\">Credit Limit</span>\n        <strong><%= currency(card.credit_limit) %></strong>\n      </div>\n      <div style=\"display:flex;justify-content:space-between;padding:14px 24px;border-bottom:1px solid var(--border);\">\n        <span style=\"color:var(--text-gray);\">Current Balance</span>\n        <strong style=\"color:var(--danger);\"><%= currency(card.balance || 0) %></strong>\n      </div>\n      <% } %>\n      <div style=\"display:flex;justify-content:space-between;padding:14px 24px;border-bottom:1px solid var(--border);\">\n        <span style=\"color:var(--text-gray);\">Applied</span>\n        <strong><%= moment(card.applied_at).format('DD MMM YYYY') %></strong>\n      </div>\n      <div style=\"display:flex;justify-content:space-between;padding:14px 24px;border-bottom:1px solid var(--border);\">\n        <span style=\"color:var(--text-gray);\">Issued</span>\n        <strong><%= card.issued_at ? moment(card.issued_at).format('DD MMM YYYY') : '—' %></strong>\n      </div>\n      <div style=\"display:flex;justify-content:space-between;padding:14px 24px;\">\n        <span style=\"color:var(--text-gray);\">Expires</span>\n        <strong><%= card.expiry_date || '—' %></strong>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <div class=\"card-header\">\n      <h3 class=\"card-title\">📊 Card Activity</h3>\n    </div>\n    <div class=\"card-body\" style=\"padding:0;\">\n      <% if (card.is_lost || card.status === 'blocked') { %>\n        <div class=\"alert alert-danger\" style=\"margin:16px;\">\n          <span class=\"alert-icon\">🚨</span>\n          <div class=\"alert-content\">\n            <div class=\"alert-title\">Card Blocked</div>\n            <p class=\"alert-message\" style=\"margin:0;\">This card has been reported as lost or stolen. Contact support to order a replacement.</p>\n          </div>\n        </div>\n      <% } else if (card.status === 'pending') { %>\n        <div class=\"alert alert-warning\" style=\"margin:16px;\">\n          <span class=\"alert-icon\">⏳</span>\n          <div class=\"alert-content\">\n            <div class=\"alert-title\">Application Pending</div>\n            <p class=\"alert-message\" style=\"margin:0;\">Your application is being reviewed. You'll be notified once a decision is made.</p>\n          </div>\n        </div>\n      <% } %>\n      <div class=\"timeline\">\n        <div class=\"timeline-item\">\n          <div class=\"timeline-time\"><%= moment(card.applied_at).format('DD MMM, HH:mm') %></div>\n          <div class=\"timeline-title\">📝 Application Submitted</div>\n          <div class=\"timeline-desc\">Application for <%= card.card_type %> received.</div>\n        </div>\n        <% if (card.status !== 'pending') { %>\n        <div class=\"timeline-item\">\n          <div class=\"timeline-time\">\n            <%= card.approved_at ? moment(card.approved_at).format('DD MMM, HH:mm') : 'Pending decision' %>\n          </div>\n          <div class=\"timeline-title\">\n            <%= card.status === 'rejected' ? '❌ Application Rejected' : '✅ Application Approved' %>\n          </div>\n          <div class=\"timeline-desc\">\n            <%= card.status === 'rejected' ? 'Application was not approved at this time.' : 'Card approved and queued for printing.' %>\n          </div>\n        </div>\n        <% } %>\n        <% if (card.status === 'active' || card.status === 'frozen') { %>\n        <div class=\"timeline-item\">\n          <div class=\"timeline-time\"><%= moment(card.issued_at).format('DD MMM, HH:mm') %></div>\n          <div class=\"timeline-title\">🎉 Card Issued</div>\n          <div class=\"timeline-desc\">Card activated and ready for use.</div>\n        </div>\n        <% } %>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\nfunction showTab(tab) {\n  document.querySelectorAll('[id$=\"Tab\"]').forEach(el => el.style.display = 'none');\n  document.querySelectorAll('.card-body button').forEach(el => { el.style.background = 'transparent'; el.style.color = 'var(--text-dark)'; el.style.fontWeight = '500'; });\n  document.getElementById(tab + 'Tab').style.display = 'grid';\n  if (tab === 'settings') document.getElementById('settingsTab').style.display = 'block';\n  event.target.style.background = 'var(--primary-alpha)';\n  event.target.style.color = 'var(--primary)';\n  event.target.style.fontWeight = '700';\n}\n</script>\n\n<%- include('../partials/layouts/user-end', { pageScripts }) -%>\n\n\n"
