var __line = 1
  , __lines = "<% const pageScripts = ['/js/home.js']; %>\n<%- include('partials/layouts/main-start') -%>\n\n<%\n%>\n<section class=\"hero\">\n  <div class=\"container hero-grid\">\n    <div>\n      <span class=\"hero-badge\">🇦🇺 Proudly Australian • APRA Regulated</span>\n      <h1>Banking that <span class=\"accent\">works as hard</span> as you do.</h1>\n      <p class=\"hero-subtitle\">\n        Experience the future of banking with United Credit Bank. Competitive rates, award-winning service, and digital tools designed for modern Australians.\n      </p>\n      <div class=\"hero-cta\">\n        <a href=\"/auth/register\" class=\"btn btn-primary btn-lg\">🚀 Open Free Account</a>\n        <a href=\"/services\" class=\"btn btn-outline btn-lg\">Explore Services</a>\n      </div>\n      <div class=\"hero-stats\">\n        <div>\n          <div class=\"hero-stat-num\"><%= stats.customers.toLocaleString() %>K+</div>\n          <div class=\"hero-stat-label\">Happy Customers</div>\n        </div>\n        <div>\n          <div class=\"hero-stat-num\"><%= stats.accounts.toLocaleString() %></div>\n          <div class=\"hero-stat-label\">Active Accounts</div>\n        </div>\n        <div>\n          <div class=\"hero-stat-num\"><%= stats.branches %></div>\n          <div class=\"hero-stat-label\">Branches AU-Wide</div>\n        </div>\n        <div>\n          <div class=\"hero-stat-num\"><%= stats.years %>+</div>\n          <div class=\"hero-stat-label\">Years Serving</div>\n        </div>\n      </div>\n    </div>\n    <div class=\"hero-card hero-media-card reveal-on-scroll is-visible\">\n      <div class=\"bank-card\">\n        <div class=\"bank-card-chip\"></div>\n        <div class=\"bank-card-number\">4539 •••• •••• 2026</div>\n        <div class=\"bank-card-bottom\">\n          <div class=\"bank-card-holder\">\n            <span class=\"bank-card-label\">Card Holder</span>\n            <span class=\"bank-card-value\">UCB CUSTOMER</span>\n          </div>\n          <div class=\"bank-card-holder\" style=\"align-items:flex-end;\">\n            <span class=\"bank-card-label\">Expires</span>\n            <span class=\"bank-card-value\">12/30</span>\n          </div>\n          <div class=\"bank-card-logo\">\n            UCB<small>VISA PLATINUM</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"hero-slideshow\" id=\"heroSlideshow\" aria-label=\"United Credit Bank feature showcase\">\n        <div class=\"hero-slide is-active\">\n          <img src=\"/images/herobank.jpg\" alt=\"United Credit Bank hero banking scene\" class=\"hero-slide-image\">\n        </div>\n        <div class=\"hero-slide\">\n          <img src=\"/images/mobileapp.jpg\" alt=\"United Credit Bank mobile banking app visual\" class=\"hero-slide-image\">\n        </div>\n        <div class=\"hero-slide\">\n          <img src=\"/images/growthchart.jpg\" alt=\"United Credit Bank growth and investment visual\" class=\"hero-slide-image\">\n        </div>\n        <div class=\"hero-slide\">\n          <img src=\"/images/walletcards.jpg\" alt=\"United Credit Bank wallet and cards visual\" class=\"hero-slide-image\">\n        </div>\n        <div class=\"hero-slide-caption\">\n          <span class=\"hero-slide-kicker\">Live Digital Banking</span>\n          <strong>Modern everyday banking with richer visuals and faster actions.</strong>\n        </div>\n        <div class=\"hero-slide-dots\" aria-label=\"Hero slideshow controls\">\n          <button type=\"button\" class=\"hero-slide-dot is-active\" aria-label=\"Show slide 1\"></button>\n          <button type=\"button\" class=\"hero-slide-dot\" aria-label=\"Show slide 2\"></button>\n          <button type=\"button\" class=\"hero-slide-dot\" aria-label=\"Show slide 3\"></button>\n          <button type=\"button\" class=\"hero-slide-dot\" aria-label=\"Show slide 4\"></button>\n        </div>\n      </div>\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:20px;\">\n        <div style=\"padding:12px;background:var(--bg-gray);border-radius:var(--radius);\">\n          <div style=\"font-size:0.7rem;color:var(--text-light);text-transform:uppercase;letter-spacing:0.05em;\">Savings Rate</div>\n          <div style=\"font-size:1.4rem;font-weight:800;color:var(--primary);\">4.25%</div>\n          <div style=\"font-size:0.75rem;color:var(--text-gray);\">High Interest Account</div>\n        </div>\n        <div style=\"padding:12px;background:var(--bg-gray);border-radius:var(--radius);\">\n          <div style=\"font-size:0.7rem;color:var(--text-light);text-transform:uppercase;letter-spacing:0.05em;\">Home Loan</div>\n          <div style=\"font-size:1.4rem;font-weight:800;color:var(--primary);\">5.49%</div>\n          <div style=\"font-size:0.75rem;color:var(--text-gray);\">Variable Rate p.a.</div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section class=\"section\">\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <span class=\"section-eyebrow\">Why Australians Choose Us</span>\n      <h2>Banking built for your lifestyle</h2>\n      <p>From everyday transactions to long-term wealth building, United Credit Bank has the tools and expertise to help you succeed financially.</p>\n    </div>\n    <div class=\"features-grid\">\n      <div class=\"feature-card reveal-on-scroll\">\n        <div class=\"feature-icon\"><img src=\"/images/icons/instant-transfer.svg\" alt=\"Instant transfer icon\"></div>\n        <h3>Instant Transfers</h3>\n        <p>Send and receive money instantly with Osko and NPP payments. Transfer up to $10,000 per day with zero fees.</p>\n        <ul class=\"feature-list\">\n          <li>24/7 real-time payments</li>\n          <li>PayID support for simple addresses</li>\n          <li>$0 transfer fees on local payments</li>\n        </ul>\n      </div>\n      <div class=\"feature-card reveal-on-scroll\">\n        <div class=\"feature-icon\"><img src=\"/images/icons/global-banking.svg\" alt=\"Global banking icon\"></div>\n        <h3>Global Banking</h3>\n        <p>Travel the world or send money to loved ones overseas. Competitive exchange rates with transparent low fees.</p>\n        <ul class=\"feature-list\">\n          <li>50+ currencies supported</li>\n          <li>Low $25 international fee</li>\n          <li>Locked-in exchange rates</li>\n        </ul>\n      </div>\n      <div class=\"feature-card reveal-on-scroll\">\n        <div class=\"feature-icon\"><img src=\"/images/icons/secure-banking.svg\" alt=\"Secure banking icon\"></div>\n        <h3>Bank-Grade Security</h3>\n        <p>Your money is safe with military-grade encryption, 2-factor authentication, and 100% fraud protection guarantee.</p>\n        <ul class=\"feature-list\">\n          <li>256-bit SSL encryption</li>\n          <li>Real-time fraud monitoring</li>\n          <li>Zero-liability fraud policy</li>\n        </ul>\n      </div>\n      <div class=\"feature-card reveal-on-scroll\">\n        <div class=\"feature-icon\"><img src=\"/images/icons/mobile-banking.svg\" alt=\"Mobile banking icon\"></div>\n        <h3>Award-Winning App</h3>\n        <p>Manage your entire financial life on the go with our 5-star rated mobile and internet banking platforms.</p>\n        <ul class=\"feature-list\">\n          <li>4.9★ on App Store (AU)</li>\n          <li>Biometric login & Face ID</li>\n          <li>Instant push notifications</li>\n        </ul>\n      </div>\n      <div class=\"feature-card reveal-on-scroll\">\n        <div class=\"feature-icon\"><img src=\"/images/icons/rates-growth.svg\" alt=\"Rates growth icon\"></div>\n        <h3>Competitive Rates</h3>\n        <p>Some of Australia's best rates on savings accounts, home loans, personal loans, and credit cards.</p>\n        <ul class=\"feature-list\">\n          <li>Up to 4.25% p.a. savings</li>\n          <li>Home loans from 5.49%</li>\n          <li>0% balance transfer cards</li>\n        </ul>\n      </div>\n      <div class=\"feature-card reveal-on-scroll\">\n        <div class=\"feature-icon\"><img src=\"/images/icons/support-team.svg\" alt=\"Support team icon\"></div>\n        <h3>Local Support</h3>\n        <p>Speak with real Australians based in our Sydney, Melbourne, and Brisbane support centres 7 days a week.</p>\n        <ul class=\"feature-list\">\n          <li>1300 UCBANK hotline</li>\n          <li>Live chat agents on standby</li>\n          <li>58 branches across Australia</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section class=\"section\">\n  <div class=\"container\">\n    <div class=\"visual-showcase\">\n      <div class=\"showcase-copy reveal-on-scroll\">\n        <span class=\"section-eyebrow\">Digital Experience</span>\n        <h2>Bank anywhere with a smoother, more secure experience</h2>\n        <p>United Credit Bank now combines richer visuals, faster actions, stronger transfer protection, and a cleaner responsive layout so the platform feels like a modern banking product on every screen.</p>\n        <div class=\"hero-cta\">\n          <a href=\"/auth/register\" class=\"btn btn-primary\">Open Your Account</a>\n          <a href=\"/auth/login\" class=\"btn btn-outline\">Internet Banking Login</a>\n        </div>\n      </div>\n      <div class=\"showcase-art reveal-on-scroll\">\n        <div class=\"showcase-stack\">\n          <img src=\"/images/mobileapp.jpg\" alt=\"United Credit Bank mobile dashboard visual\" class=\"showcase-image showcase-primary-image float-y\">\n          <div class=\"showcase-mini-grid\">\n            <img src=\"/images/piggybank.jpg\" alt=\"Savings visual\" class=\"showcase-tile\">\n            <img src=\"/images/walletcards.jpg\" alt=\"Cards visual\" class=\"showcase-tile\">\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section class=\"section section-alt\">\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <span class=\"section-eyebrow\">Our Services</span>\n      <h2>Complete banking solutions</h2>\n      <p>Everything you need to manage your money, grow your wealth, and achieve your financial goals — all in one place.</p>\n    </div>\n    <div class=\"services-grid\">\n      <div class=\"service-card reveal-on-scroll\">\n        <div class=\"service-icon\"><img src=\"/images/icons/secure-banking.svg\" alt=\"Bank account icon\"></div>\n        <div style=\"flex:1;min-width:0;\">\n          <h4>Everyday Bank Accounts</h4>\n          <p>Fee-free everyday accounts with unlimited free transactions, Apple Pay, Google Pay, and Samsung Pay built-in.</p>\n          <a href=\"/auth/register\" class=\"service-link\">Open Account →</a>\n        </div>\n      </div>\n      <div class=\"service-card reveal-on-scroll\">\n        <div class=\"service-icon\"><img src=\"/images/icons/mobile-banking.svg\" alt=\"Cards icon\"></div>\n        <div style=\"flex:1;min-width:0;\">\n          <h4>Credit & Debit Cards</h4>\n          <p>From low-rate debit cards to platinum rewards credit cards with travel insurance and lounge access benefits.</p>\n          <a href=\"/services\" class=\"service-link\">View Cards →</a>\n        </div>\n      </div>\n      <div class=\"service-card reveal-on-scroll\">\n        <div class=\"service-icon\"><img src=\"/images/icons/rates-growth.svg\" alt=\"Home loan icon\"></div>\n        <div style=\"flex:1;min-width:0;\">\n          <h4>Home Loans</h4>\n          <p>First home buyer? Investor? Refinancer? We've got competitive rates and expert mortgage brokers ready.</p>\n          <a href=\"/services\" class=\"service-link\">Compare Rates →</a>\n        </div>\n      </div>\n      <div class=\"service-card reveal-on-scroll\">\n        <div class=\"service-icon\"><img src=\"/images/icons/support-team.svg\" alt=\"Personal loan icon\"></div>\n        <div style=\"flex:1;min-width:0;\">\n          <h4>Personal Loans</h4>\n          <p>Borrow from $2,000 to $50,000 for anything — travel, weddings, renovations, or debt consolidation.</p>\n          <a href=\"/services\" class=\"service-link\">Calculate Repayments →</a>\n        </div>\n      </div>\n      <div class=\"service-card reveal-on-scroll\">\n        <div class=\"service-icon\"><img src=\"/images/icons/global-banking.svg\" alt=\"International transfer icon\"></div>\n        <div style=\"flex:1;min-width:0;\">\n          <h4>International Transfers</h4>\n          <p>Send money overseas to over 100 countries with competitive exchange rates and low flat fees from $25.</p>\n          <a href=\"/services\" class=\"service-link\">Send Money Now →</a>\n        </div>\n      </div>\n      <div class=\"service-card reveal-on-scroll\">\n        <div class=\"service-icon\"><img src=\"/images/icons/instant-transfer.svg\" alt=\"Business banking icon\"></div>\n        <div style=\"flex:1;min-width:0;\">\n          <h4>Business Banking</h4>\n          <p>Complete business banking with transaction accounts, merchant facilities, business loans, and tax tools.</p>\n          <a href=\"/services\" class=\"service-link\">Business Solutions →</a>\n        </div>\n      </div>\n      <div class=\"service-card reveal-on-scroll\">\n        <div class=\"service-icon\"><img src=\"/images/icons/rates-growth.svg\" alt=\"Term deposit icon\"></div>\n        <div style=\"flex:1;min-width:0;\">\n          <h4>Term Deposits</h4>\n          <p>Lock in guaranteed returns with Australia's best term deposit rates — from 3 months to 5 year terms.</p>\n          <a href=\"/services\" class=\"service-link\">See Rates →</a>\n        </div>\n      </div>\n      <div class=\"service-card reveal-on-scroll\">\n        <div class=\"service-icon\"><img src=\"/images/icons/secure-banking.svg\" alt=\"Bill pay icon\"></div>\n        <div style=\"flex:1;min-width:0;\">\n          <h4>Bill Payments (BPAY)</h4>\n          <p>Pay over 45,000+ Australian billers with BPAY. Schedule recurring payments and never miss a due date.</p>\n          <a href=\"/services\" class=\"service-link\">Learn More →</a>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section class=\"section testimonial-section\">\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <span class=\"section-eyebrow\">Customer Stories</span>\n      <h2>Loved by thousands of Australians</h2>\n      <p>Real stories from real United Credit Bank customers who transformed their financial future with us.</p>\n    </div>\n    <div class=\"testimonials-grid\">\n      <div class=\"testimonial\">\n        <div class=\"testimonial-quote\">\"</div>\n        <p class=\"testimonial-text\">Switching to United Credit Bank was the best financial decision I've made. Their mobile app is so intuitive, I feel like my bank actually understands me. The savings rates are unbeatable!</p>\n        <div class=\"testimonial-author\">\n          <div class=\"testimonial-avatar\">SC</div>\n          <div>\n            <div class=\"testimonial-name\">Sarah Chen</div>\n            <div class=\"testimonial-loc\">Melbourne, VIC</div>\n          </div>\n        </div>\n      </div>\n      <div class=\"testimonial\">\n        <div class=\"testimonial-quote\">\"</div>\n        <p class=\"testimonial-text\">As a small business owner, I need a bank that moves fast. United Credit Bank approved my $150K business loan in 48 hours and their international transfer fees saved me thousands last year.</p>\n        <div class=\"testimonial-author\">\n          <div class=\"testimonial-avatar\">MT</div>\n          <div>\n            <div class=\"testimonial-name\">Marcus Thompson</div>\n            <div class=\"testimonial-loc\">Brisbane, QLD</div>\n          </div>\n        </div>\n      </div>\n      <div class=\"testimonial\">\n        <div class=\"testimonial-quote\">\"</div>\n        <p class=\"testimonial-text\">First home buyer dream! Their mortgage brokers walked us through every step, and secured us a rate 0.5% lower than the big four. We saved over $200/month on repayments. 10/10.</p>\n        <div class=\"testimonial-author\">\n          <div class=\"testimonial-avatar\">JA</div>\n          <div>\n            <div class=\"testimonial-name\">James & Amelia R.</div>\n            <div class=\"testimonial-loc\">Sydney, NSW</div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section class=\"cta-section\">\n  <div class=\"container\">\n    <div class=\"cta-box\">\n      <h2>Ready to bank better? Start today, free.</h2>\n      <p>Join over 250,000 Australians who've already made the switch to United Credit Bank. Open your free account in under 2 minutes.</p>\n      <a href=\"/auth/register\" class=\"btn btn-light btn-lg\">🏦 Open Free Account Now</a>\n    </div>\n  </div>\n</section>\n\n<%- include('partials/layouts/main-end', { pageScripts }) -%>\n"
