    ; __append("\n\n        <button type=\"submit\" class=\"btn btn-primary btn-lg btn-block\">✅ Submit Loan Application</button>\n      </form>\n    </div>\n  </div>\n\n  <div>\n    <div class=\"card\" style=\"margin-bottom:20px;\">\n      <div class=\"card-header\"><h3 class=\"card-title\">🧮 Repayment Calculator</h3></div>\n      <div class=\"card-body\">\n        <div style=\"text-align:center;padding:10px 0 20px;\">\n          <div style=\"font-size:0.8rem;color:var(--text-light);text-transform:uppercase;letter-spacing:0.05em;margin-bottom:6px;\">Estimated Monthly Repayment</div>\n          <div style=\"font-size:2.8rem;font-weight:900;color:var(--primary);\" id=\"monthlyPayment\">$0</div>\n          <div style=\"color:var(--text-gray);font-size:0.9rem;margin-top:4px;\" id=\"interestRate\">Interest rate —% p.a.</div>\n        </div>\n        <div style=\"padding:16px;background:var(--bg-gray);border-radius:var(--radius);\">\n          <div style=\"display:grid;gap:10px;\">\n            <div style=\"display:flex;justify-content:space-between;font-size:0.9rem;\">\n              <span style=\"color:var(--text-gray);\">Principal Amount</span>\n              <strong id=\"sumPrincipal\">$0</strong>\n            </div>\n            <div style=\"display:flex;justify-content:space-between;font-size:0.9rem;\">\n              <span style=\"color:var(--text-gray);\">Total Interest</span>\n              <strong id=\"sumInterest\" style=\"color:var(--warning);\">$0</strong>\n            </div>\n            <div style=\"padding-top:10px;border-top:2px solid var(--border);margin-top:6px;display:flex;justify-content:space-between;font-weight:700;font-size:1.05rem;\">\n              <span>Total Repayment</span>\n              <strong id=\"sumTotal\" style=\"color:var(--text-dark);\">$0</strong>\n            </div>\n          </div>\n        </div>\n        <div class=\"alert alert-info\" style=\"margin-top:16px;margin-bottom:0;\">\n          <span class=\"alert-icon\">ℹ️</span>\n          <div class=\"alert-content\">\n            <div class=\"alert-title\">Estimate only</div>\n            <p class=\"alert-message\" style=\"margin:0;font-size:0.85rem;\">Based on current indicative rates. Final rate and repayment will be confirmed upon approval based on your circumstances.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-header\"><h3 class=\"card-title\">💡 Why UCB Loans?</h3></div>\n      <div class=\"card-body\" style=\"padding:0;\">\n        <div style=\"padding:16px 20px;border-bottom:1px solid var(--border);display:flex;gap:12px;\">\n          <div style=\"font-size:1.5rem;\">⚡</div>\n          <div>\n            <div style=\"font-weight:700;font-size:0.95rem;\">Fast approval</div>\n            <div style=\"font-size:0.85rem;color:var(--text-light);\">Most customers get a decision same day</div>\n          </div>\n        </div>\n        <div style=\"padding:16px 20px;border-bottom:1px solid var(--border);display:flex;gap:12px;\">\n          <div style=\"font-size:1.5rem;\">💰</div>\n          <div>\n            <div style=\"font-weight:700;font-size:0.95rem;\">No hidden fees</div>\n            <div style=\"font-size:0.85rem;color:var(--text-light);\">Redraw facilities & offset accounts available</div>\n          </div>\n        </div>\n        <div style=\"padding:16px 20px;display:flex;gap:12px;\">\n          <div style=\"font-size:1.5rem;\">🔒</div>\n          <div>\n            <div style=\"font-weight:700;font-size:0.95rem;\">APRA regulated</div>\n            <div style=\"font-size:0.85rem;color:var(--text-light);\">Australian bank, Australian standards, Australian support</div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\nfunction updateLoanCalc() {\n  const sel = document.getElementById('loanTypeSelect').selectedOptions[0];\n  let P = parseFloat(document.getElementById('loanAmount').value) || 0;\n  const rate = parseFloat(sel?.dataset.rate) || 6;\n  const n = parseInt(document.getElementById('termMonths').value) || 12;\n  const r = (rate / 100) / 12;\n  const emi = r > 0 ? (P * r * Math.pow(1 + r, n)) / (Math.pow(1 + r, n) - 1) : P / n;\n  const total = emi * n;\n  const interest = total - P;\n  document.getElementById('monthlyPayment').textContent = '$' + emi.toLocaleString('en-AU', {maximumFractionDigits: 0, minimumFractionDigits: 0});\n  document.getElementById('interestRate').textContent = 'Interest rate ' + rate.toFixed(2) + '% p.a.';\n  document.getElementById('sumPrincipal').textContent = '$' + P.toLocaleString('en-AU');\n  document.getElementById('sumInterest').textContent = '$' + interest.toLocaleString('en-AU', {maximumFractionDigits: 0});\n  document.getElementById('sumTotal').textContent = '$' + total.toLocaleString('en-AU', {maximumFractionDigits: 0});\n}\ndocument.getElementById('loanAmount').addEventListener('input', updateLoanCalc);\nsetTimeout(updateLoanCalc, 100);\n</script>\n\n")
