var __line = 1
  , __lines = "<% const pageScripts = ['/js/transfers.js']; %>\n<%- include('../partials/layouts/user-start') -%>\n\n<a href=\"/transfers\" class=\"btn btn-outline btn-sm\" style=\"margin-bottom:16px;\">← All Transfers</a>\n\n<div class=\"grid-2\">\n  <div class=\"card\">\n    <div class=\"card-header\"><h3 class=\"card-title\">🌍 International Transfer (SWIFT)</h3></div>\n    <div class=\"card-body\">\n      <% if (!hasTransferPin) { %>\n        <div class=\"alert alert-warning\">\n          <span class=\"alert-icon\">🔐</span>\n          <div class=\"alert-content\">\n            <div class=\"alert-title\">Transfer PIN Required</div>\n            <p class=\"alert-message\">Create your transfer PIN in <a href=\"/user/settings\">Settings</a> before sending international payments.</p>\n          </div>\n        </div>\n      <% } %>\n      <form method=\"POST\" action=\"/transfers/international\" id=\"intlTransferForm\">\n        <div class=\"form-group\">\n          <label class=\"form-label\">From Account (AUD) *</label>\n          <select name=\"from_account\" required class=\"form-select\">\n            <% accounts.forEach(acc => { %>\n              <option value=\"<%= acc.id %>\" <%= (typeof selectedAccountId !== 'undefined' && selectedAccountId === acc.id) ? 'selected' : '' %>>\n                <%= acc.account_type %> • Available: <%= currency(acc.available_balance) %>\n              </option>\n            <% }) %>\n          </select>\n        </div>\n\n        <div class=\"form-group\">\n          <label class=\"form-label\">Destination Currency *</label>\n          <select name=\"currency\" required class=\"form-select\" id=\"currencySelect\">\n            <% Object.keys(rates).forEach(curr => { %>\n              <option value=\"<%= curr %>\" data-rate=\"<%= rates[curr] %>\"><%= curr %> • 1 AUD = <%= rates[curr] %> <%= curr %></option>\n            <% }) %>\n          </select>\n        </div>\n\n        <div class=\"form-grid\">\n          <div class=\"form-group\">\n            <label class=\"form-label\">Destination Country *</label>\n            <select name=\"country\" required class=\"form-select\">\n              <% countries.forEach(c => { %>\n                <option value=\"<%= c.name %>\"><%= c.name %></option>\n              <% }) %>\n            </select>\n          </div>\n          <div class=\"form-group\">\n            <label class=\"form-label\">SWIFT / BIC Code *</label>\n            <input type=\"text\" name=\"swift_code\" required class=\"form-input\" placeholder=\"e.g. NATAUS33\" maxlength=\"11\">\n          </div>\n        </div>\n\n        <div class=\"form-group\">\n          <label class=\"form-label\">Recipient Name *</label>\n          <input type=\"text\" name=\"to_name\" required class=\"form-input\" id=\"toNameIntl\" placeholder=\"Full legal name per bank\">\n        </div>\n\n        <div class=\"form-grid\">\n          <div class=\"form-group\">\n            <label class=\"form-label\">IBAN / Account No. *</label>\n            <input type=\"text\" name=\"iban\" required class=\"form-input\" placeholder=\"IBAN or account number\">\n          </div>\n          <div class=\"form-group\">\n            <label class=\"form-label\">Bank Name</label>\n            <input type=\"text\" name=\"bank_name\" class=\"form-input\" placeholder=\"e.g. Barclays London\">\n          </div>\n        </div>\n\n        <div class=\"form-group\">\n          <label class=\"form-label\">Amount (AUD) to send *</label>\n          <div style=\"position:relative;\">\n            <span style=\"position:absolute;left:16px;top:50%;transform:translateY(-50%);font-weight:600;color:var(--text-gray);\">$</span>\n            <input type=\"number\" name=\"amount\" id=\"amountIntl\" required min=\"100\" step=\"0.01\" value=\"500\" class=\"form-input\" style=\"padding-left:32px;\">\n          </div>\n          <span class=\"form-hint\">Min. $100 AUD. Fixed $25 fee. Large amounts may require approval.</span>\n        </div>\n\n        <div class=\"form-group\">\n          <label class=\"form-label\">Reference / Purpose of Payment</label>\n          <input type=\"text\" name=\"reference\" class=\"form-input\" placeholder=\"e.g. Family support, Invoice #...\">\n        </div>\n\n        <div class=\"form-group\">\n          <label class=\"form-label\">Transfer PIN *</label>\n          <input type=\"password\" name=\"transfer_pin\" required class=\"form-input\" placeholder=\"Enter your 4 to 6 digit transfer PIN\" inputmode=\"numeric\" pattern=\"[0-9]{4,6}\" maxlength=\"6\">\n          <span class=\"form-hint\">Your transfer PIN is checked before the payment is submitted for processing.</span>\n        </div>\n\n        <button type=\"submit\" class=\"btn btn-primary btn-lg btn-block\">✅ Review & Send Transfer</button>\n      </form>\n    </div>\n  </div>\n\n  <div>\n    <div class=\"card\" style=\"margin-bottom:20px;\">\n      <div class=\"card-header\"><h3 class=\"card-title\">💱 Transfer Conversion</h3></div>\n      <div class=\"card-body\" id=\"intlSummaryBox\">\n        <div style=\"color:var(--text-light);text-align:center;padding:20px;\">Calculating...</div>\n      </div>\n    </div>\n\n    <div class=\"card\" style=\"margin-bottom:20px;\">\n      <div class=\"card-header\"><h3 class=\"card-title\">⏱️ Timelines</h3></div>\n      <div class=\"card-body\" style=\"padding:0;\">\n        <div style=\"padding:14px 20px;border-bottom:1px solid var(--border);display:flex;gap:12px;align-items:flex-start;\">\n          <div style=\"width:28px;height:28px;border-radius:50%;background:var(--primary-alpha);color:var(--primary);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:0.8rem;flex-shrink:0;\">1</div>\n          <div>\n            <div style=\"font-weight:600;\">Sent today</div>\n            <div style=\"font-size:0.82rem;color:var(--text-light);\">We process your transfer and debit AUD</div>\n          </div>\n        </div>\n        <div style=\"padding:14px 20px;border-bottom:1px solid var(--border);display:flex;gap:12px;align-items:flex-start;\">\n          <div style=\"width:28px;height:28px;border-radius:50%;background:var(--primary-alpha);color:var(--primary);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:0.8rem;flex-shrink:0;\">2</div>\n          <div>\n            <div style=\"font-weight:600;\">1-2 business days</div>\n            <div style=\"font-size:0.82rem;color:var(--text-light);\">SWIFT network routes via partner banks</div>\n          </div>\n        </div>\n        <div style=\"padding:14px 20px;display:flex;gap:12px;align-items:flex-start;\">\n          <div style=\"width:28px;height:28px;border-radius:50%;background:var(--success-light);color:var(--success);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:0.8rem;flex-shrink:0;\">3</div>\n          <div>\n            <div style=\"font-weight:600;\">2-3 business days</div>\n            <div style=\"font-size:0.82rem;color:var(--text-light);\">Funds arrive in recipient's bank</div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-header\"><h3 class=\"card-title\">ℹ️ Fees</h3></div>\n      <div class=\"card-body\" style=\"padding:0;\">\n        <div style=\"display:flex;justify-content:space-between;padding:14px 20px;border-bottom:1px solid var(--border);\">\n          <span>Fixed transfer fee</span>\n          <strong>$25.00</strong>\n        </div>\n        <div style=\"display:flex;justify-content:space-between;padding:14px 20px;border-bottom:1px solid var(--border);\">\n          <span>Approval required</span>\n          <strong>Amounts ≥ $5,000</strong>\n        </div>\n        <div style=\"display:flex;justify-content:space-between;padding:14px 20px;\">\n          <span>Daily limit</span>\n          <strong>$50,000 AUD</strong>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\nfunction updateIntlSummary() {\n  const aud = parseFloat(document.getElementById('amountIntl').value) || 0;\n  const sel = document.getElementById('currencySelect');\n  const rate = parseFloat(sel.selectedOptions[0]?.dataset.rate || 1);\n  const curr = sel.value;\n  const fee = 25;\n  const totalAud = aud + fee;\n  const foreignAmt = aud * rate;\n  const needsApproval = aud >= 5000;\n  document.getElementById('intlSummaryBox').innerHTML = `\n    <div style=\"padding:4px 0 16px;border-bottom:1px dashed var(--border);margin-bottom:16px;\">\n      <div style=\"font-size:0.78rem;color:var(--text-light);text-transform:uppercase;letter-spacing:0.05em;margin-bottom:6px;\">You Send (AUD)</div>\n      <div style=\"font-size:2rem;font-weight:800;color:var(--danger);\">A$${aud.toLocaleString('en-AU', {minimumFractionDigits: 2})}</div>\n    </div>\n    <div style=\"display:flex;justify-content:space-between;padding:6px 0;font-size:0.9rem;\">\n      <span style=\"color:var(--text-gray);\">Exchange rate</span>\n      <strong>1 AUD = ${rate} ${curr}</strong>\n    </div>\n    <div style=\"display:flex;justify-content:space-between;padding:6px 0;font-size:0.9rem;\">\n      <span style=\"color:var(--text-gray);\">Service fee</span>\n      <strong>A$${fee.toFixed(2)}</strong>\n    </div>\n    <div style=\"padding:14px 0 4px;border-top:2px solid var(--border);margin-top:8px;\">\n      <div style=\"font-size:0.78rem;color:var(--text-light);text-transform:uppercase;letter-spacing:0.05em;margin-bottom:4px;\">Recipient receives</div>\n      <div style=\"font-size:1.5rem;font-weight:800;color:var(--success);\">${curr} ${foreignAmt.toLocaleString('en-AU', {minimumFractionDigits: 2})}</div>\n    </div>\n    <div style=\"padding-top:8px;border-top:1px solid var(--border);margin-top:12px;display:flex;justify-content:space-between;\">\n      <span style=\"font-weight:700;\">Total cost (AUD)</span>\n      <strong style=\"color:var(--primary);font-size:1.1rem;\">A$${totalAud.toLocaleString('en-AU', {minimumFractionDigits: 2})}</strong>\n    </div>\n    ${needsApproval ? `<div class=\"alert alert-warning\" style=\"margin-top:16px;margin-bottom:0;\"><span class=\"alert-icon\">⏳</span><div class=\"alert-content\"><div class=\"alert-title\">Approval Required</div><p class=\"alert-message\" style=\"margin:0;\">Large transfers require security review. Usually approved within 4 business hours.</p></div></div>` : ''}\n  `;\n}\ndocument.getElementById('amountIntl').addEventListener('input', updateIntlSummary);\ndocument.getElementById('currencySelect').addEventListener('change', updateIntlSummary);\nsetTimeout(updateIntlSummary, 100);\n</script>\n\n<%- include('../partials/layouts/user-end', { pageScripts }) -%>\n\n"
