var __line = 1
  , __lines = "<!DOCTYPE html>\n<html lang=\"en-AU\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <meta name=\"theme-color\" content=\"#C8102E\">\n  <title><%= title %></title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n  <link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css\" rel=\"stylesheet\" integrity=\"sha384-QWTKZyjpPEjISv5WaRU9OFeRpok6YctnYmDr5pNlyT2bRjXh0JMhjY6hW+ALEwIH\" crossorigin=\"anonymous\">\n  <link rel=\"stylesheet\" href=\"/css/style.css\">\n  <link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect width='100' height='100' rx='20' fill='%23C8102E'/><text x='50' y='62' font-size='48' font-family='Arial' font-weight='800' text-anchor='middle' fill='white'>U</text></svg>\">\n</head>\n<body>\n  <div class=\"layout\">\n    <%- include('../partials/sidebar-user') %>\n    <div class=\"main\">\n      <%- include('../partials/topbar') %>\n      <div class=\"content\">\n        <% if (!kyc || kyc.status !== 'approved') { %>\n          <div class=\"alert alert-warning\">\n            <span class=\"alert-icon\">🆔</span>\n            <div class=\"alert-content\">\n              <div class=\"alert-title\">Complete Your Identity Verification</div>\n              <p class=\"alert-message\"><%= kyc && kyc.status === 'pending' ? 'Your KYC is being reviewed. Once approved you\\'ll unlock cards, loans, and higher limits.' : 'Verify your identity now to access all banking features including cards, loans, and higher transaction limits.' %></p>\n              <% if (!kyc || kyc.status === 'rejected') { %>\n                <a href=\"/kyc/submit\" class=\"btn btn-warning btn-sm\" style=\"margin-top:8px;\">Complete KYC Now</a>\n              <% } %>\n            </div>\n          </div>\n        <% } %>\n\n        <div class=\"stats-grid\">\n          <div class=\"stat-card\">\n          <div class=\"stat-header\">\n            <div>\n              <div class=\"stat-label\">Total Balance</div>\n              <div class=\"stat-value\"><%= currency(totalBalance) %></div>\n            </div>\n            <div class=\"stat-icon stat-icon-primary\">💰</div>\n          </div>\n          <div class=\"stat-change up\">Available now: <%= currency(totalAvailable) %> across <%= accounts.length %> accounts</div>\n        </div>\n          <div class=\"stat-card\">\n          <div class=\"stat-header\">\n            <div>\n              <div class=\"stat-label\">Total Credits</div>\n              <div class=\"stat-value\" style=\"color:var(--success);\">+<%= currency(totalCredits || 0) %></div>\n            </div>\n            <div class=\"stat-icon stat-icon-success\">💳</div>\n          </div>\n          <div class=\"stat-change\"><%= cards.length %> active card<%= cards.length !== 1 ? 's' : '' %> • Limit <%= currency(totalCardCredit || 0) %></div>\n        </div>\n          <div class=\"stat-card\">\n          <div class=\"stat-header\">\n            <div>\n              <div class=\"stat-label\">Total Debits</div>\n              <div class=\"stat-value\" style=\"color:var(--danger);\">-<%= currency(totalDebits || 0) %></div>\n            </div>\n            <div class=\"stat-icon stat-icon-warning\">⬆️</div>\n          </div>\n          <div class=\"stat-change\">Completed outgoing payments and fees</div>\n        </div>\n          <div class=\"stat-card\">\n          <div class=\"stat-header\">\n            <div>\n              <div class=\"stat-label\">Pending Approvals</div>\n              <div class=\"stat-value\" style=\"color:var(--warning);\"><%= pendingTransfers + pendingLoans + pendingCards %></div>\n            </div>\n            <div class=\"stat-icon stat-icon-info\">⏳</div>\n          </div>\n          <div class=\"stat-change\">\n            <% const loanTotal = loans.filter(l => l.status === 'disbursed' || l.status === 'active').reduce((s,l) => s + parseFloat(l.remaining_balance || l.loan_amount), 0); %>\n            <%= loanTotal > 0 ? currency(loanTotal) + ' active loan balance' : 'No active loan balance' %>\n          </div>\n        </div>\n        </div>\n\n        <div class=\"quick-actions\">\n          <a href=\"/transfers/local\" class=\"quick-action\">\n            <div class=\"quick-action-icon\">↔️</div>\n            <span class=\"quick-action-label\">Local Transfer</span>\n          </a>\n          <a href=\"/transfers/international\" class=\"quick-action\">\n            <div class=\"quick-action-icon\">🌍</div>\n            <span class=\"quick-action-label\">International</span>\n          </a>\n          <a href=\"/billpay/pay\" class=\"quick-action\">\n            <div class=\"quick-action-icon\">📄</div>\n            <span class=\"quick-action-label\">Pay a Bill</span>\n          </a>\n          <a href=\"/cards/apply\" class=\"quick-action\">\n            <div class=\"quick-action-icon\">💳</div>\n            <span class=\"quick-action-label\">Apply Card</span>\n          </a>\n          <a href=\"/billpay/deposit/new\" class=\"quick-action\">\n            <div class=\"quick-action-icon\">⬇️</div>\n            <span class=\"quick-action-label\">Deposit</span>\n          </a>\n          <a href=\"/billpay/withdraw/new\" class=\"quick-action\">\n            <div class=\"quick-action-icon\">⬆️</div>\n            <span class=\"quick-action-label\">Withdraw</span>\n          </a>\n          <a href=\"/loans/apply\" class=\"quick-action\">\n            <div class=\"quick-action-icon\">🏦</div>\n            <span class=\"quick-action-label\">Apply Loan</span>\n          </a>\n          <a href=\"/accounts/open/new\" class=\"quick-action\">\n            <div class=\"quick-action-icon\">📁</div>\n            <span class=\"quick-action-label\">New Account</span>\n          </a>\n        </div>\n\n        <div class=\"dashboard-spotlight card\">\n          <div class=\"dashboard-spotlight-media\">\n            <img src=\"/images/herobank.jpg\" alt=\"United Credit Bank banking overview visual\">\n          </div>\n          <div class=\"dashboard-spotlight-copy\">\n            <span class=\"section-eyebrow\">Smarter Dashboard</span>\n            <h3>Everything important in one secure view</h3>\n            <p>Track balances, move money, review approvals, and manage your cards with a cleaner digital banking experience built around your daily actions.</p>\n            <div class=\"dashboard-spotlight-actions\">\n              <a href=\"/transfers\" class=\"btn btn-primary btn-sm\">Move Money</a>\n              <a href=\"/user/settings\" class=\"btn btn-outline btn-sm\">Security Settings</a>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"grid-2-1\">\n          <div>\n            <div class=\"card\">\n              <div class=\"card-header\">\n              <h3 class=\"card-title\">My Accounts</h3>\n              <a href=\"/accounts\" class=\"btn btn-outline btn-sm\">View All</a>\n            </div>\n            <div class=\"card-body\" style=\"padding:16px;\">\n              <% if (accounts.length === 0) { %>\n                <div class=\"empty-state\">\n                  <div class=\"empty-state-icon\">🏦</div>\n                  <h4>No accounts yet</h4>\n                  <p>Open your first account to get started.</p>\n                </div>\n              <% } %>\n              <% accounts.forEach(acc => { %>\n                <div class=\"account-card\" style=\"margin-bottom:0;border:none;padding:20px;border-radius:var(--radius-lg);margin-bottom:12px;\">\n                  <div class=\"account-card-header\">\n                    <div class=\"account-type\">\n                      <div class=\"account-type-icon\">💳</div>\n                      <div>\n                        <div class=\"account-name\"><%= acc.account_type %></div>\n                        <div class=\"account-number\">BSB <%= acc.bsb %> • <%= acc.account_number.slice(acc.account_number.length - 4) %></div>\n                      </div>\n                    </div>\n                    <div class=\"account-balance\">\n                      <div class=\"account-balance-label\">Available</div>\n                      <div class=\"account-balance-value\"><%= currency(acc.available_balance) %></div>\n                      <div style=\"font-size:0.8rem;color:var(--text-light);text-align:right;\">Balance: <%= currency(acc.balance) %></div>\n                    </div>\n                  </div>\n                  <div class=\"account-actions\">\n                    <a href=\"/accounts/<%= acc.id %>\" class=\"btn btn-light btn-sm\">Details</a>\n                    <a href=\"/transfers/local?from=<%= acc.id %>\" class=\"btn btn-outline btn-sm\">Transfer</a>\n                    <a href=\"/user/statements?account=<%= acc.id %>\" class=\"btn btn-light btn-sm\">Statement</a>\n                  </div>\n                </div>\n              <% }) %>\n            </div>\n          </div>\n\n            <div style=\"margin-top:20px;\" class=\"card\">\n              <div class=\"card-header\">\n                <h3 class=\"card-title\">Recent Transactions</h3>\n                <a href=\"/transfers/history\" class=\"btn btn-outline btn-sm\">View All</a>\n              </div>\n              <div class=\"card-body\" style=\"padding:0;\">\n                <% if (transactions.length === 0) { %>\n                  <div class=\"empty-state\">\n                    <div class=\"empty-state-icon\">📋</div>\n                    <h4>No transactions yet</h4>\n                    <p>Your recent transactions will show up here.</p>\n                  </div>\n                <% } else { %>\n                  <div class=\"table-wrap\">\n                    <table class=\"table\">\n                      <tbody>\n                        <% transactions.slice(0, 8).forEach(tx => { \n                          const isOut = !['deposit', 'loan_disbursement'].includes(tx.transaction_type);\n                          const displayType = tx.transaction_type.replace(/_/g, ' ').replace(/\\b\\w/g, l => l.toUpperCase());\n                        %>\n                          <tr>\n                            <td style=\"width:44px;padding-right:0;\">\n                              <div style=\"width:40px;height:40px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:<%= isOut ? 'var(--danger-light)' : 'var(--success-light)' %>;color:<%= isOut ? 'var(--danger)' : 'var(--success)' %>;font-size:1.1rem;\">\n                                <%= isOut ? '➖' : '➕' %>\n                              </div>\n                            </td>\n                            <td>\n                              <div style=\"font-weight:600;font-size:0.9rem;\"><%= tx.recipient_name || tx.description || displayType %></div>\n                              <div style=\"font-size:0.78rem;color:var(--text-light);\"><%= displayType %></div>\n                            </td>\n                            <td style=\"text-align:right;\">\n                              <div style=\"font-weight:700;font-size:0.95rem;color:<%= isOut ? 'var(--danger)' : 'var(--success)' %>;\">\n                                <%= isOut ? '-' : '+' %><%= currency(tx.amount) %>\n                              </div>\n                              <span class=\"status-badge status-<%= tx.status %>\" style=\"margin-left:auto;\"><%= tx.status %></span>\n                            </td>\n                          </tr>\n                        <% }) %>\n                      </tbody>\n                    </table>\n                  </div>\n                <% } %>\n              </div>\n            </div>\n          </div>\n\n          <div>\n            <div class=\"dashboard-image-strip\">\n              <div class=\"dashboard-image-card\">\n                <img src=\"/images/piggybank.jpg\" alt=\"Savings image\">\n                <div class=\"dashboard-image-copy\">\n                  <strong>Savings Growth</strong>\n                  <span>Build reserves with disciplined saving and better visibility.</span>\n                </div>\n              </div>\n              <div class=\"dashboard-image-card\">\n                <img src=\"/images/growthchart.jpg\" alt=\"Growth image\">\n                <div class=\"dashboard-image-copy\">\n                  <strong>Performance View</strong>\n                  <span>Monitor balances, cards, loans, and transaction activity faster.</span>\n                </div>\n              </div>\n            </div>\n\n            <% if (cards.length > 0) { %>\n              <div class=\"card\" style=\"margin-bottom:20px;\">\n                <div class=\"card-header\">\n                  <h3 class=\"card-title\">My Card</h3>\n                  <a href=\"/cards\" class=\"btn btn-outline btn-sm\">Manage</a>\n                </div>\n                <div class=\"card-body\">\n                  <% \n                    const card = cards.find(c => ['active', 'approved'].includes(c.status)) || cards[0];\n                  %>\n                  <div class=\"card-visual\" style=\"margin:0 auto 16px;\">\n                    <div class=\"card-visual-type\">\n                      <div class=\"card-brand\">UCB</div>\n                      <span class=\"card-type-label\"><%= card.card_type %></span>\n                    </div>\n                    <div class=\"card-visual-chip\"></div>\n                    <div class=\"card-visual-number\">\n                      <% \n                        const cn = card.card_number; \n                        const masked = cn.slice(0,4) + ' ' + '•••• ' + '•••• ' + cn.slice(-4);\n                      %>\n                      <%= masked %>\n                    </div>\n                    <div class=\"card-visual-footer\">\n                      <div>\n                        <div class=\"card-field-label\">Holder</div>\n                        <div class=\"card-field-value\"><%= card.cardholder_name %></div>\n                      </div>\n                      <div>\n                        <div class=\"card-field-label\">Exp</div>\n                        <div class=\"card-field-value\"><%= card.expiry_date %></div>\n                      </div>\n                    </div>\n                  </div>\n                  <div style=\"text-align:center;\">\n                    <span class=\"status-badge status-<%= card.status %>\"><%= card.status %></span>\n                    <div style=\"margin-top:10px;font-size:0.85rem;color:var(--text-gray);\">\n                      Daily limit: <%= currency(card.daily_limit) %>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            <% } else { %>\n              <div class=\"card\" style=\"margin-bottom:20px;\">\n                <div class=\"card-header\"><h3 class=\"card-title\">💳 Get Your Card</h3></div>\n                <div class=\"card-body\" style=\"text-align:center;\">\n                  <div style=\"font-size:3rem;margin-bottom:12px;\">💳</div>\n                  <h4 style=\"margin-bottom:8px;\">No cards yet</h4>\n                  <p style=\"margin-bottom:16px;\">Apply for a debit or credit card in minutes.</p>\n                  <a href=\"/cards/apply\" class=\"btn btn-primary btn-block\">Apply for Card</a>\n                </div>\n              </div>\n            <% } %>\n\n            <div class=\"card\" style=\"margin-bottom:20px;\">\n              <div class=\"card-header\"><h3 class=\"card-title\">🔔 Notifications</h3></div>\n              <div class=\"card-body\" style=\"padding:0;max-height:360px;overflow-y:auto;\">\n                <% if (notifications.length === 0) { %>\n                  <div class=\"empty-state\" style=\"padding:32px 16px;\">\n                    <div class=\"empty-state-icon\" style=\"width:56px;height:56px;font-size:1.4rem;\">🔔</div>\n                    <h4 style=\"font-size:1rem;\">All caught up!</h4>\n                    <p style=\"font-size:0.85rem;\">No new notifications.</p>\n                  </div>\n                <% } %>\n                <% notifications.forEach(n => { %>\n                  <div style=\"padding:14px 20px;border-bottom:1px solid var(--border);display:flex;gap:12px;align-items:flex-start;\">\n                    <div style=\"width:36px;height:36px;border-radius:50%;background:var(--bg-gray);display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:1rem;\">\n                      <%= n.type === 'success' ? '✅' : n.type === 'warning' ? '⚠️' : n.type === 'error' ? '❌' : 'ℹ️' %>\n                    </div>\n                    <div style=\"min-width:0;flex:1;\">\n                      <div style=\"font-weight:600;font-size:0.9rem;margin-bottom:2px;\"><%= n.title %></div>\n                      <div style=\"font-size:0.82rem;color:var(--text-gray);margin-bottom:4px;\"><%= n.message %></div>\n                      <div style=\"font-size:0.7rem;color:var(--text-light);\"><%= moment(n.created_at).fromNow() %></div>\n                    </div>\n                  </div>\n                <% }) %>\n              </div>\n            </div>\n\n            <div class=\"card\">\n              <div class=\"card-header\"><h3 class=\"card-title\">🇦🇺 Need Help?</h3></div>\n              <div class=\"card-body\">\n                <div class=\"dashboard-help-visual\">\n                  <img src=\"/images/walletcards.jpg\" alt=\"Wallet and cards image\">\n                </div>\n                <div style=\"padding:14px;background:var(--primary-alpha);border-radius:var(--radius);margin-bottom:12px;\">\n                  <div style=\"font-weight:600;font-size:0.9rem;color:var(--primary);\">📞 1300 UCBANK</div>\n                  <div style=\"font-size:0.8rem;color:var(--text-gray);\">Mon-Fri 8am-8pm AEST</div>\n                </div>\n                <a href=\"/user/support\" class=\"btn btn-outline btn-block\">Contact Support</a>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <% if (typeof error !== 'undefined' && error) { %>\n    <div id=\"toast-error\" class=\"alert alert-danger\" style=\"position:fixed;top:20px;right:20px;z-index:9999;max-width:400px;box-shadow:0 10px 30px rgba(0,0,0,0.15);\">\n      <span class=\"alert-icon\">⚠️</span>\n      <div class=\"alert-content\">\n        <div class=\"alert-title\">Error</div>\n        <p class=\"alert-message\"><%= error %></p>\n      </div>\n    </div>\n  <% } %>\n  <% if (typeof success !== 'undefined' && success) { %>\n    <div id=\"toast-success\" class=\"alert alert-success\" style=\"position:fixed;top:20px;right:20px;z-index:9999;max-width:400px;box-shadow:0 10px 30px rgba(0,0,0,0.15);\">\n      <span class=\"alert-icon\">✓</span>\n      <div class=\"alert-content\">\n        <div class=\"alert-title\">Success</div>\n        <p class=\"alert-message\"><%= success %></p>\n      </div>\n    </div>\n  <% } %>\n\n  <script src=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js\" integrity=\"sha384-YvpcrYf0tY3lHB60NNkmXc5s9fDVZLESaAA55NDzOxhy9GkcIdslK1eN7N6jIeHz\" crossorigin=\"anonymous\"></script>\n  <script src=\"/js/common.js\"></script>\n  <script src=\"/js/user-dashboard.js\"></script>\n</body>\n</html>\n"
