var __line = 1
  , __lines = "<% const pageScripts = ['/js/transfers.js']; %>\n<%- include('../partials/layouts/user-start') -%>\n\n<div class=\"card\" style=\"margin-bottom:20px;\">\n  <div class=\"card-header\">\n    <h3 class=\"card-title\">📊 Account Statement</h3>\n    <div style=\"display:flex;gap:8px;\">\n      <select id=\"accountSelect\" class=\"form-select\" style=\"min-width:240px;\">\n        <% accounts.forEach(acc => { %>\n          <option value=\"<%= acc.id %>\" <%= selectedAccount && selectedAccount.id === acc.id ? 'selected' : '' %>>\n            <%= acc.account_type %> • <%= currency(acc.balance) %>\n          </option>\n        <% }) %>\n      </select>\n      <a href=\"#\" class=\"btn btn-outline btn-sm\" onclick=\"window.print();return false;\">🖨️ Print</a>\n      <button class=\"btn btn-outline btn-sm\">⬇️ Export CSV</button>\n    </div>\n  </div>\n  <% if (selectedAccount) { %>\n    <div class=\"filter-bar\">\n      <div class=\"filter-group\">\n        <span class=\"filter-label\">From Date</span>\n        <input type=\"date\" class=\"form-input\" id=\"fromDate\">\n      </div>\n      <div class=\"filter-group\">\n        <span class=\"filter-label\">To Date</span>\n        <input type=\"date\" class=\"form-input\" id=\"toDate\">\n      </div>\n      <div class=\"filter-group\">\n        <span class=\"filter-label\">Type</span>\n        <select class=\"form-select\" id=\"typeFilter\">\n          <option value=\"all\">All Types</option>\n          <option>deposit</option>\n          <option>withdrawal</option>\n          <option>local_transfer</option>\n          <option>international_transfer</option>\n          <option>bill_payment</option>\n          <option>loan_payment</option>\n          <option>loan_disbursement</option>\n        </select>\n      </div>\n      <button class=\"btn btn-primary btn-sm\" onclick=\"filterStatement()\">🔍 Filter</button>\n    </div>\n  <% } %>\n  <% if (selectedAccount) { %>\n    <div style=\"padding:20px 24px;background:var(--bg-light);border-bottom:1px solid var(--border);\">\n      <div class=\"grid-4\" style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:20px;\">\n        <div>\n          <div style=\"font-size:0.75rem;color:var(--text-light);text-transform:uppercase;letter-spacing:0.05em;\">Account</div>\n          <div style=\"font-weight:700;font-size:1rem;margin-top:4px;\"><%= selectedAccount.account_type %></div>\n          <div style=\"font-size:0.85rem;color:var(--text-gray);font-family:monospace;\">BSB <%= selectedAccount.bsb %> • <%= selectedAccount.account_number %></div>\n        </div>\n        <div>\n          <div style=\"font-size:0.75rem;color:var(--text-light);text-transform:uppercase;letter-spacing:0.05em;\">Current Balance</div>\n          <div style=\"font-weight:800;font-size:1.5rem;color:var(--text-dark);margin-top:4px;\"><%= currency(selectedAccount.balance) %></div>\n        </div>\n        <div>\n          <div style=\"font-size:0.75rem;color:var(--text-light);text-transform:uppercase;letter-spacing:0.05em;\">Total Credits</div>\n          <div style=\"font-weight:700;font-size:1.25rem;color:var(--success);margin-top:4px;\">\n            +<%= currency(statementCredits || 0) %>\n          </div>\n        </div>\n        <div>\n          <div style=\"font-size:0.75rem;color:var(--text-light);text-transform:uppercase;letter-spacing:0.05em;\">Total Debits</div>\n          <div style=\"font-weight:700;font-size:1.25rem;color:var(--danger);margin-top:4px;\">\n            -<%= currency(statementDebits || 0) %>\n          </div>\n        </div>\n      </div>\n    </div>\n  <% } %>\n  <div class=\"table-wrap\">\n    <table class=\"table\">\n      <thead>\n        <tr>\n          <th>Date</th>\n          <th>Type / Description</th>\n          <th>Reference</th>\n          <th style=\"text-align:right;\">Amount</th>\n          <th>Status</th>\n        </tr>\n      </thead>\n      <tbody>\n        <% if (transactions.length === 0) { %>\n          <tr><td colspan=\"5\"><div class=\"empty-state\"><div class=\"empty-state-icon\">📋</div><h4>No transactions</h4><p>No transactions found for this period.</p></div></td></tr>\n        <% } %>\n        <% transactions.forEach(tx => { \n          const isOut = ['withdrawal','local_transfer','international_transfer','bill_payment','loan_payment','admin_adjustment'].includes(tx.transaction_type) && parseFloat(tx.amount) < 0 || ['withdrawal','local_transfer','international_transfer','bill_payment','loan_payment'].includes(tx.transaction_type);\n          const displayType = tx.transaction_type.replace(/_/g, ' ').replace(/\\b\\w/g, l => l.toUpperCase());\n        %>\n          <tr style=\"cursor:pointer;\" onclick=\"location.href='/transfers/<%= tx.id %>'\">\n            <td><%= moment(tx.created_at).format('DD MMM YYYY HH:mm') %></td>\n            <td>\n              <div style=\"font-weight:600;font-size:0.9rem;\"><%= tx.recipient_name || tx.description || displayType %></div>\n              <div style=\"font-size:0.8rem;color:var(--text-light);\"><%= displayType %></div>\n            </td>\n            <td style=\"font-family:monospace;font-size:0.85rem;\"><%= tx.reference || '—' %></td>\n            <td style=\"text-align:right;\">\n              <div style=\"font-weight:700;color:<%= isOut ? 'var(--danger)' : 'var(--success)' %>\">\n                <%= isOut ? '-' : '+' %><%= currency(Math.abs(parseFloat(tx.amount))) %>\n              </div>\n              <% if (parseFloat(tx.fee) > 0) { %>\n                <div style=\"font-size:0.75rem;color:var(--text-light);\">Fee: <%= currency(tx.fee) %></div>\n              <% } %>\n            </td>\n            <td><span class=\"status-badge status-<%= tx.status %>\"><%= tx.status %></span></td>\n          </tr>\n        <% }) %>\n      </tbody>\n    </table>\n  </div>\n</div>\n\n<%- include('../partials/layouts/user-end', { pageScripts }) -%>\n\n\n"
  , __filename = "/bundle/user/statements.ejs";
